export default [{"id":275,"question":"ما حكم مَن ذهب للجهاد من دون علم والديه، واستشهد رحمه الله، هل يدخل في حكم المُجاهد في سبيل الله؟","title":"حكم من ذهب للجهاد دون علم والديه واستشهد","answer":"الجواب: نرجو له ذلك إن شاء الله، نرجو له ذلك، نرجو له أن يكون شهيدًا مغفورًا له؛ لأنَّ ذهابه بغير إذن والديه عن اجتهادٍ وعن رغبةٍ في الخير، واستئذان الوالدين فيه من الإشكال ما فيه في مثل هذا، فنرجو له الخير العظيم.","link":"https://binbaz.org.sa/fatwas/4272/حكم-من-ذهب-للجهاد-دون-علم-والديه-واستشهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0320.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":284,"question":"إنني شابٌّ أريد أن أتزوج بفتاةٍ معروفةٍ لدى قريتنا أنها صالحة، فرفضتْ أمي لأسبابٍ تافهةٍ..... وأبي وافق، فهل أتزوج من غير موافقة أمي أم لا؟","title":"هل يجوز لشاب الزواج بفتاة دون رضا أمه؟","answer":"الجواب: إذا كانت البنتُ طيبةً في دينها ومناسبة؛ فلا حرج: إنما الطاعة في المعروف، لا حرج أن تتزوج بغير رضا أبيك أو أمك، ولكن مهما أمكن أن تُرضيهما، وأن يكون الزواجُ عن رضاهما؛ فهذا أكمل وأطيب، فحاول ما استطعتَ من ذلك لعلك تنجح، وإن وجدتَ مَن يقوم مقامها حتى تجمع بين المصلحتين فهذا أفضل وأطيب، أما إذا اشتدت الحاجةُ إليها وهي صالحةٌ في نفسها؛ فليس من شرط ذلك أن يرضى أبوك أو أمُّك؛ لأنَّ الرسول ﷺ يقول: إنما الطاعة في المعروف، وليس من المعروف أن تدع زوجةً صالحةً من أجل امتناعهما أو أحدهما من ذلك.","link":"https://binbaz.org.sa/fatwas/4282/هل-يجوز-لشاب-الزواج-بفتاة-دون-رضا-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0331.mp3","categories":["بر الوالدين"]},{"id":753,"question":"إنَّ والدي سامحه الله يُلزمني أن آخذ بنت أخيه المتوفي، وأنا لا أرغبها، زواجًا، ولا أعرف فيها عيبًا شرعيًّا، إلا أن نفسي لا ترضاها، فهل أكون عاقًّا إن أنا امتنعتُ وأخذتُ غيرها؟","title":"حكم من يلزمه والده بالزواج من فتاة معيّنة","answer":"الجواب: إن تيسر لك طاعة والدك فلعل الله يجعل فيها خيرًا، ولعل الله يكتب بينك وبينها المودة، فهذا أصلح وأحسن؛ تُلبي دعوة والدك، وتطيع أمره، ولعل الله يجعل في ذلك خيرًا كثيرًا، قال الله تعالى: فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا [النساء:19]، فالمؤمن لا يدري، فقد يكره شيئًا وقد ينفر من شيءٍ ويكون فيه الخير له، وطاعة والدك من أهم القربات والطاعات، وقد تجب إذا كان في المعروف، وفيه منفعة له ومصلحة له.\nفينبغي لك أن تُلبي دعوته، وتجيب طَلْبَتَه وتتزوجها، ولعل الله يجعل في هذا خيرًا كثيرًا، فإن لم تُناسب فأنت معذورٌ بعد ذلك إذا طلقتها والتمستَ غيرها، وإن وضع الله في قلبك المحبة فالحمد لله.\nالذي أنصح به أن تجيب دعوة والدك وطَلْبَتَه، وأن تتزوج بنت عمك ما دمت لا تعلم فيها مانعًا، فهذا خيرٌ إن شاء الله للجميع.","link":"https://binbaz.org.sa/fatwas/20640/حكم-من-يلزمه-والده-بالزواج-من-فتاة-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0564أن والدي يلزمني أن آخذ بنت أخته المتوفي وأنا لا أرغبها ولا أعرف فيها عيب هل أكون عاقاُ أن رفضت.mp3","categories":["بر الوالدين"]},{"id":769,"question":"أعيش مع والدي وذريتي في بلادي في فقرٍ شديدٍ، وقد سافرتُ إلى الرياض لطلب المعيشة، مع أنَّ والديَّ لم يرضيا بذلك، فهل فعلي هذا جائزٌ، مع أنَّ المصلحة تقتضيه بشدةٍ؟","title":"حكم السفر لطلب الرزق دون رضا الوالدين","answer":"الجواب: إذا كنت مُضطرًّا فلا بأس؛ لأن الرسول عليه السلام يقول: إنما الطاعة في المعروف، فإذا كان بقاؤك يضرُّك ويضرُّهما، وسافرتَ لطلب الرزق فلا بأس عليك، لكن مع الكلام الطيب، تسترضيهما، وتُخاطبهما بالتي هي أحسن، وتُوضح الأمر الذي اضطرَّك للسفر، وهما يرضيان عنك إن شاء الله؛ لأنك محسنٌ فيهما، أما إذا وجدتَ عندهما العمل وما يُغنيك عن السفر وهما في حاجةٍ إليك؛ فلا تُسافر إلا بإذنهما.","link":"https://binbaz.org.sa/fatwas/20697/حكم-السفر-لطلب-الرزق-دون-رضا-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0595أعيش أنا ووالدي وأسرتي في فقر شديد وسافرت طلب الرزق ووالدي لم يرضيا بسفري فماالحكم؟ ابن باز.mp3","categories":["بر الوالدين"]},{"id":1311,"question":"إنني أُحب الجهادَ، وقد امتزج حبُّه في قلبي، ولا أستطيع أن أصبر عنه، وقد استأذنتُ والدتي ولم تُوافق، ولكن تأثرت كثيرًا، ولا أستطيع أن أبتعد عن الجهاد، سماحة الشيخ، إنَّ أمنيتي في الحياة هي الجهاد في سبيل الله، وأن أُقتل في سبيله، وأمي لا تُوافق، دُلَّني جزاك الله خيرًا؟","title":"هل يجب استئذان الوالدين في الجهاد؟","answer":"الجواب:\nجهادك في أمك جهادٌ عظيمٌ، الزم أمك، وأحسن إليها، إلا إذا أمرك ولي الأمر بالجهاد فبادر، قال النبيُّ ﷺ: إذا استُنفرتم فانفروا، وما دام ما طُلبت فأحسن لأمك، وارحمها، وبرها جهادٌ عظيمٌ قدَّمه النبيُّ ﷺ على الجهاد، قيل: يا رسول الله، أي الأعمال أفضل؟ قال: إيمان بالله ورسوله، قيل: ثم أي؟ قال: بر الوالدين، قيل: ثم أي؟ قال: الجهاد في سبيل الله، فقدَّم برَّهما على الجهاد.\nوجاءه رجلٌ يستأذنه قال: يا رسول الله، إني أحبُّ أن أُجاهد، قال: هل استأذنتَ والديك؟ قال: لا، قال: ارجع فاستأذنهما، وفي اللفظ الآخر قال: ففيهما فجاهد.\nفهذه الوالدة ارحمها وأحسن إليها حتى تسمح لك، وأما إذا نزل البلاءُ بك فدافع عن نفسك، ولا حول ولا قوة إلا بالله، أو أمرك وليُّ الأمر بالنَّفير تنفر، ولو بغير رضاهما، قال النبيُّ ﷺ: وإذا استنفرتم فانفروا، قال الله جلَّ وعلا: إِلَّا تَنْفِرُوا يُعَذِّبْكُمْ عَذَابًا أَلِيمًا [التوبة:39].","link":"https://binbaz.org.sa/fatwas/21358/هل-يجب-استىذان-الوالدين-في-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1101أريد الجهاد في سبيل الله وأمي غير موافقة فما الحكم؟ ابن باز فتاوى.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":1616,"question":"إذا كان الشخص يريد الجهادَ فهل يستأذن والديه؟","title":"حكم استئذان الوالدين في الجهاد","answer":"الجواب:\nيستأذنهما، قال: ارجع فاستأذنهما، فإن أذنا لك وإلا فبرّهما، إلا إذا كان الجهاد واجبًا، مثل: حصر البلادَ عدوٌّ، أو كان بين الصَّفَّين، أو استنفره الإمامُ؛ فلا إذن، ففي هذه المواضع الثلاثة يجب عليه القتال ولا يستأذن.","link":"https://binbaz.org.sa/fatwas/21720/حكم-استىذان-الوالدين-في-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استئذان الوالدين في الجهاد.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":1637,"question":"مَن تزوَّج بغير إذن والديه هل يُعتبر عاقًّا؟","title":"هل من العقوق الزواج بغير إذن الوالدين؟","answer":"الجواب:\nلا، ما هو بعاقٍّ، فالزواج واجبٌ عليه إذا كان يشتهي، لكن إذا شاورهما يكون أحسن وأفضل.\nس: يعني: هما غاضبان عليه حتى يُطَلِّق، فهل يكون عاقًّا؟\nج: لا، ما هو بعاقٍّ، إذا كانت الزوجةُ مناسبةً وطيبةً وليس فيها بأسٌ عليهما فلا يلزمه الطلاق: إنما الطاعة في المعروف.","link":"https://binbaz.org.sa/fatwas/21742/هل-من-العقوق-الزواج-بغير-اذن-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من العقوق الزواج بغير إذن الوالدين.mp3","categories":["بر الوالدين"]},{"id":1750,"question":"واحد من الشَّباب يريد الزواج بغير علم أبيه، فهل هذا يجوز؟","title":"ما حكم الزواج بغير علم الوالد أو رضاه؟","answer":"الجواب:\nما فيه مانع إذا كان أبوه يمنعه من الزواج، أما إذا كان الزواج من امرأةٍ لا يرضاها والده فلا ينبغي له أن يَعْجَل، وعليه أن يلتمس امرأةً يرضاها، أما إذا كان والده لا يُريده أن يتعفف فلا بأس أن يتزوج ولو ما دَرَى والده، حتى يعفّ نفسه.","link":"https://binbaz.org.sa/fatwas/21857/ما-حكم-الزواج-بغير-علم-الوالد-او-رضاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الزواج بغير استئذان الوالد.mp3","categories":["بر الوالدين"]},{"id":2171,"question":"أحدهم يقول: إذا ألزمني والدي وقال: لا تدخل بيتي إذا ما خطبت الفلانية بنت فلان الفلانية؟","title":"حكم من يلزمه والده بخطبة فتاة معينة","answer":"الجواب:\nإن كانت ما تُناسبه فلا تلزمه طاعته: إنما الطاعة في المعروف، فلا تلزمه طاعته إلا في المعروف، إن كانت مناسبةً فينبغي له طاعة والده، وإن لم تكن مناسبة؛ لعدم جمالها، أو لسوء دينها؛ ما يلزمه طاعة والده، فالنكاح ليس سهلًا، وأمره عظيم.\nس: يقول: والدي سيطردني من البيت......؟\nج: إذا تزوجها من أجل والده جزاه الله خيرًا.\nس: يعني: يصبر؟\nج: نعم يصبر، لعل الله يجمع بينهما: فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا [النساء:19]، فقد يتزوجها وهو كاره ثم يجمع الله بينهما.","link":"https://binbaz.org.sa/fatwas/22292/حكم-من-يلزمه-والده-بخطبة-فتاة-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طاعة الوالدين في أمر النكاح.mp3","categories":["الخِطْبَة والاختيار ","بر الوالدين"]},{"id":5106,"question":"إذا كان والدي يمنعني من صحبة الأخيار، وأنا أحس بأني لا أستغني عنهم في ديني وانقطاعي خطر علي، فهل يجوز لي مخالفة أمره؟","title":"ماذا يفعل من يأمره والده بترك مصاحبة الأخيار؟","answer":"الجواب: نعم نعم، يقول النبي ﷺ: إنما الطاعة في المعروف فإذا قال لك أبوك: لا تصاحب الأخيار؛ لا تطعه في ذلك، ولكن بالكلام الطيب والأسلوب الحسن.. يا والدي كذا ويا والدي كذا، وإذا كان لم يسمح فلا مانع من صحبتهم وإن لم يعلم بذلك، حتى ولو علم لا يضر، يقول النبي ﷺ: إنما الطاعة في المعروف. لكن مع هذا تجتهد في حُسن الصُّحبة، والكلام الطيب مع الوالد بالأسلوب الحسن والرفق، وإذا تيسر أن تعمل الخير وهو لا يعلم حتى لا يزداد الشر بينكما فهذا حسن. فالمقصود أنك لا تطيعه في خلاف الشرع، وهكذا لو قال لك: لا تصل في الجماعة، أو أرادك أن تتزوج امرأة لا تصلح؛ فعليك بذات الدين ولو عصيته، لكن بالأسلوب الحسن والرفق والكلام الطيب؛ حتى تجمع بين المصلحتين.","link":"https://binbaz.org.sa/fatwas/30014/ماذا-يفعل-من-يامره-والده-بترك-مصاحبة-الاخيار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 33.mp3","categories":["بر الوالدين"]},{"id":5108,"question":"فضيلة الشيخ  حفظه الله: السلام عليكم ورحمة الله وبركاته، يوجد بعض من الشباب الصالح يعق والديه ويرفض مطالبهم بحجة أنه يوجد درس أو محاضرة يريد الذهاب إليها، ماذا عن فعلهم هذا، هل صحيح أم يعتبر عقوق للوالدين، نرجو النصيحة لهؤلاء؟","title":"هل يجوز الانشغال عن حاجات الوالدين بطلب العلم؟","answer":"الجواب: عقوق الوالدين منكر لا يجوز، وعقوقهما قطيعتهما والإساءة إليهما أو إيذاؤهما أو سبهما أو عدم الإنفاق عليهما مع الحاجة كل هذا من العقوق، فإذا كان لوالديه حاجة فيه بدّاها وقدمها على ذهابه إلى حضور المحاضرة، أو الدرس؛ لأن هذا شيء جزئي لا يمنعه من طلب العلم ولا يمنعه من صحبة الأخيار، بل هو عارض فينبغي له في هذه الحالة أن يقدم طاعة الوالد؛ لأن بره واجب، فالواجب أن يقدم طاعته في هذه المسائل الجزئية، وأن يقدم ذلك على أن يحضر المحاضرة الفلانية أو العزيمة الفلانية أو الندوة الفلانية أو ما أشبه ذلك؛ لأن البر واجب فلا يترك لمستحب. ثم أيضًا يجب على الأولاد الحرص غاية الحرص على بر الوالدين حتى ولو كانا كافرين، فكيف وهما مسلمان؟ الله يقول في حق الوالدين الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما كافران، فكيف بالمسلمين! الواجب برهما والإحسان إليهما والرفق بهما وخفض الجناح لهما وتليين الكلام معهما والسمع والطاعة لهما في المعروف، هذا هو الواجب على الولد ذكرًا كان أو أنثى، صغيرًا أو كبيرًا.","link":"https://binbaz.org.sa/fatwas/30016/هل-يجوز-الانشغال-عن-حاجات-الوالدين-بطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 35.mp3","categories":["بر الوالدين"]},{"id":6281,"question":"ما هو حكم الشرع في أخ مسلم أعزب يخشى على نفسه فتنة النساء، وتقدم لأخت ذات دين، ورضيت به، لكن والديه يطلبون في الزوجة أن تكون ذات نسب، وأن تكون حاملة لشهادة علمية عالية، هل يطيع والديه، أم يرضى بزواجه من الصالحة؟","title":"عدم طاعة الوالدين في رفضهم الزواج من المتدينة غير النسيبة","answer":"الجواب: إذا وجد امرأة صالحة، مناسبة؛ يتزوجها ولو ليس معها شهادات، ولا معروفة بنسبها، إذا كانت امرأة في نفسها صالحة، وليس لهما طاعة في هذا؛ إنما الطاعة في المعروف، لكن يخاطبهم بالتي هي أحسن، ويجتهد في إرضائهما، ولا يكون عنيفًا معهما، حقهما عظيم، لكن يلاحظهما بالطريقة الحسنى.. وللأولياء أن يطالبوا بهذا الشيء، وأن يعرف النسب، هذا يجوز عند جمع من أهل العلم، لكن مسألة الشهادة، وما الشهادة! وأن تكون كذا، فهو ليس بلازم، أما النسب فأمره على كل حال له وجاهة عند كثير من أهل العلم، ولكن لا يضر، سواء كانت مولاة، أو أعجمية، أو من قريش، أو من غيرها، لا يضر إِنَّ أَكْرَمَكُمْ عِندَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] ليس بشرط.","link":"https://binbaz.org.sa/fatwas/1798/عدم-طاعة-الوالدين-في-رفضهم-الزواج-من-المتدينة-غير-النسيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_637.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":6323,"question":"وآخر يقول: أريد الجهاد في سبيل الله، وفي أفغانستان، ولكني لي والدة لا تسمح لي بذلك؛ لأنها تحبني حبًا كثيرًا، فما موقفي منها؟","title":"حكم طاعة الوالدين في عدم الذهاب إلى الجهاد","answer":"الجواب: عليك أن تطيع والدتك، ولا تجاهد إذا قالت أمك: لا فلا، فالجهاد فيها، النبي ﷺ جاءه رجل يستأذنه، فقال: أحي والداك؟ قال: نعم، قال: ارجع فاستأذنهما فإن أذنا وإلا فبرهما، وفي رواية أخرى: ففيهما فجاهد وجاءه رجل .. أمه فقال: الزمها وأمره بعدم مخالفتها، وعدم الخروج عن طاعتها بالذهاب إلى الجهاد.  السؤال: وإن كان له إخوة؟ الجواب: وإن كان له إخوة كلهم عليهم السمع، والطاعة في هذا الأمر؛ لأن الجهاد فرض كفاية. السؤال: إذا كان الأبوان كافرين؟ الجواب: هذا محل نظر؛ إن كانا كافرين فمحل نظر، وإن كان الله قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفاً [لقمان:15] الله أمر بمصاحبتهما معروفًا، وهما كافران، إن كانا على الشرك أمر الله أن يصاحبا بالمعروف، أما كونهما يطاعان في ترك الجهاد فهذا محل نظر.","link":"https://binbaz.org.sa/fatwas/1899/حكم-طاعة-الوالدين-في-عدم-الذهاب-الى-الجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_682.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":6458,"question":"خطبت بنتًا تصلي، وتصوم، وتحافظ على الفروض، ولكن أمي لا تريدها زوجة لي؛ لخلاف بين أهلها، ومصممة على ذلك، فهل أطيع أمي، أم ماذا أفعل؟","title":"حكم من خطب بنتا ذات دين مع كون الأم ترفضها","answer":"الجواب: لا تعجل في طاعة أمك من الطاعة في المعروف، الطاعة في المعروف، لا في المعاصي، فالزوجة مهمة، فإذا كانت جيدة في دينها، ومستقيمة؛ فعليك أن تتكلم مع الوالدة بأسلوب حسن، والعبارات الطيبة؛ حتى ترضى -إن شاء الله- وعليك أن تقوم مع الزوجة بالنصيحة أيضًا حتى تقدم الأخلاق الفاضلة، والسيرة الحميدة لأمك، وحتى لا يقع التباغض بينها وبين أهلك. فالمقصود: أنك على ثغر من ثغور الإسلام، فعليك أن تعتني، ترضي أمك، وترضي من حولك بالكلام الطيب، والأسلوب الحسن، وتنصح للزوجة بأن تستعمل معهم اللين، والكلام الطيب؛ حتى يكون -إن شاء الله- بعد ذلك الاجتماع، والوئام، وحتى لا تحتاج إلى الطلاق.","link":"https://binbaz.org.sa/fatwas/2189/حكم-من-خطب-بنتا-ذات-دين-مع-كون-الام-ترفضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_814.mp3","categories":["الخِطْبَة والاختيار ","بر الوالدين"]},{"id":6488,"question":"أحد الأخوة يسأل فيقول: إن له والدة، وهناك من يعولها، ويقوم بشؤونها، ولكنها تخاف عليه دائمًا، وهو يريد الجهاد في سبيل الله، وهي لا تقبل ذلك، فما حكم ذلك؟","title":"حكم استئذان الوالدين في الجهاد في سبيل الله","answer":"الجواب: جهاده فيها أفضل، إذا كان له والدة تريد بقاءه عندها، الجهاد فيها أفضل، النبي ﷺ أمر بعض الناس لما أراد الجهاد أمره أن يلزم أمه، أمره أن يجاهد في برها، وصلتها، والإحسان إليها، وجاءه آخر يريد الجهاد فقال له: أحي والداك؟ قال: نعم. قال: ففيهما فجاهد، وفي رواية: ارجع فاستأذنهما؛ فإن أذن لك، وإلا فبرهما.  فإذا كان له والدة؛ فليلزمها، ولا يجاهد حتى تسمح له، وإذا كان والدان فلا بد من إذنهما في ذلك، وإلا فبره لهما، والإحسان إليهما أعظم من خروجه في الجهاد، في الحديث الصحيح لما سئل أي العمل أفضل؟ قال: الصلاة على وقتها قيل: ثم أي؟ قال: بر الوالدين قيل: ثم أي؟ قال: الجهاد في سبيل الله فجعل الجهاد بعد بر الوالدين، فبرهما واجب، وفريضة، والجهاد قد يكون فريضة، وقد يكون مستحبًا.","link":"https://binbaz.org.sa/fatwas/2230/حكم-استىذان-الوالدين-في-الجهاد-في-سبيل-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_850.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":6568,"question":"هل يطيع الشاب والديه إذا أمره بتأخير الزواج حتى يصبح عمره خمسة وعشرين عامًا، أو عشرين، أو حتى ينال الشهادة، وهو راغب في الزواج قبل ذلك؟ ما حكم من ليس له رغبة في الزواج؟","title":"حكم طاعة الوالدين إذا أمرا بتأخير الزواج","answer":"الجواب: أولًا: ليس لوالديه أن يقولا له هذا الكلام، ليس لوالديه أن يأمراه بالتأخير، ولا يجوز لهما أن يأمراه بالتأخير وهما يقدران على تزويجه. ثانيًا: ليس له أن يطيعهما في تأخير الزواج، وهو يرغب في الزواج، ويستطيع الزواج؛ لأن الرسول  قال: إنما الطاعة في المعروف وقال: لا طاعة لمخلوق في معصية الخالق.  فإذا أمره أبواه بالزنا، أو بالخمر؛ لا يجوز، فهكذا إذا أمراه أن يؤخر الزواج وهو يستطيع الزواج، أو يستطيعان أن يزوجانه؛ يلزمهما أن يزوجانه، ولا يجوز لهما أن يؤخرا الزواج حتى يكمل الدراسة الجامعية، أو حتى كذا وكذا ما دام يشتهي النكاح، ويريد النساء، فالخطر قائم، الخطر قائم والواجب إبعاده عن الخطر بتزويجه، هذه أسباب، والله الموفق  لكن هذه أسباب؛ فلا يجوز لهما تأخير الزواج، ولا يجوز له طاعتهما في هذا الشيء إذا استطاع أن يتخلص من هذا الأمر.","link":"https://binbaz.org.sa/fatwas/2431/حكم-طاعة-الوالدين-اذا-امرا-بتاخير-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_958.mp3","categories":["حكم الزواج وأهميته","بر الوالدين"]},{"id":6592,"question":"فأنا شاب وولي أمر فتاة -إن شاء الله- أنها صالحة، ومشكلتي: أن هذه الفتاة أختي، ولكن تقدم لخطبتها شاب صالح، ويحفظ القرآن، وأعرفه بحسن الخلق، وهي تريد هذا الشاب، بل أخبرتني أنها تحبه في الله، لكن هذا الشاب من عائلة أقل من عائلتنا في النسب، ماذا أعمل؟ فإن أختي تقول: لن أتزوج غيره، وأبناء عمها يهددون، ويقولون: لا تزوجوها، ماذا أعمل؟ وما الطريق، هل أزوجها هذا الشاب الصالح، وأدفع أبناء عمها؟","title":"حكم تزويج الولي موليته لرجل صالح لكنه دونها في النسب","answer":"الجواب: الواجب على الأولياء أن ينظروا لمولاتهم من هو أصلح لها في دينها ودنياها، ولو كان من غير قبيلتهم، بل عليهم أن ينظروا الأصلح، ولو كان من أي قبيلة، إذا صلح دينه، واستقام أمره، فإذا لم يستقيموا على ذلك، ووجدوا لها من هو يناسبها؛ فعليها أن تجتهد في موافقتهم إذا كان مستقيمًا أيضًا، ولا بأس به، وإن تنازلت عن بعض هواها؛ لمراعاة أقاربها، وأوليائها، ولسد باب الشر، والقضاء على أسباب الفرقة، والاختلاف؛ فإن تنازلها عن بعض الشيء ما دام المتنازل له لا بأس به في دينه، وإن كان دون ما أرادت في نفسها، لكنه في نفسه طيب، وفي نفسه صالح في دينه، وهو من قبيلتها، أو من قبيلة يرضاها أولياؤها؛ فهذا أولى من النزاع في الشقاق. فإذا اشتد الأمور فلم تتنازل هي، ولم يتنازل هم، رجع الأمر إلى المحكمة، وفي المحكمة الكفاية -إن شاء الله- تنظر في الأمر، وعندها الشرع المطهر، كافي في كل شيء، سبحان الذي أنزله، لكن إذا تنازل الأولياء، والتمسوا لها من هو أصلح، وتركوا تعصبهم لواحد معين، ولو كان ابن عم قريب، ما هو بلازم ابن عمه القريب، ولا هو بلازم من قبيلتها، العرب كلهم بعضهم لبعض أكفاء، وأهل الدين أكفاء، وإن كانوا ليسوا من العرب، لو زوجوها مولًى، أو عتيقًا من العتقاء، أو أعجميًا من العجم؛ فلا بأس، يقول الله -جل وعلا-: إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13]. ليس شرطًا أن القحطانية ما تأخذ إلا قحطاني، والسبيعية ما تأخذ إلا سبيعي، والهاشمية ما تأخذ إلا هاشمي، ليس من شرط هذا، النبي ﷺ زوج زينب بنت جحش أسدية أمها عمة النبي ﷺ من بني هاشم، زوجها مولًى عتيقًا زيد بن حارثة، عتيق مولى، وزوج فاطمة بنت قيس قرشية من قريش، زوجها ابنه أسامة بن زيد، وهو مولى عتيق أيضًا، وبلال تزوج من زهرية من بني زهرة من قريشن وهو عتيق من الحبشة. فالمقصود: أن هذه الأمور انطلت على كثير من الناس في العرب، وآثروها على الحق والهدى؛ فغلطوا في ذلك، فالواجب على الأولياء أن يعنوا بالأمر الشرعي، وأن يجاهدوا الشر في ذلك، فإذا غلبت .. وخافوا من شر بينهم؛ فيلتمسوا لها من يناسبها، ولو من قبيلة أخرى، لا يلزموها بشيء ما ترضاه، ما هو بلزوم بابن عمها، لا يجوز يجبروها على ابن عمها أبدًا، ولا ابن خالها، يلتمس لها من بقية القبائل، والناس الآخرين من العرب، وإن كانوا بعيدين إذا لم يرضوا بتزويجها من غير العرب، يلتمس لها من العرب، وإن زوجوها من غير العرب، من الأعاجم، من الموالي من ذوي الدين، والتقوى؛ فلا بأس، ولا حرج، والحمد لله. قد سبقهم في هذا الأخيار من هذه الأمة، وسبقهم إلى هذا الرسول ﷺ وأصحابه، فالأمر في هذا واسع يقول الله : يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا [الحجرات:13]، ثم قال بعدها إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ [الحجرات:13] ما قال: إن أكرمكم عند الله بنو هاشم، أو قريش، أو بنو تميم، أو بنو فلان لا، إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ[الحجرات:13] أتقاكم وإن كان أعجميًا، وإن كان مولى قد أعتقه فلان، أو فلان، هو الأكرم عند الله، وإن كان الذي ليس بتقي قرشيًا هاشميًا فلا قيمة له عند الله، هذا أبو لهب قرشي هاشمي من أهل النار، وأبو طالب كذلك، وأبو جهل كذلك، كلهم قرشيون، ومع ذلك صاروا إلى النار لأعمالهم الخبيثة. ثم أمر آخر: وهو أن التعصب بين القبيلة لفلان، أو فلان، يضرون به بنتهم، ويضرون به مولاتهم، هذا ظلم لا يجوز لهم، بل إذا كرهته البنت لا يحجرون عليها، ولا يعطلونها، بدل ابن عمها غيره العرب كثيرون، وغير العرب كثيرين، فإذا خطبها كفء، ولو من غير قبيلتهم، ولو من غير بني عمهم؛زوجوا، العرب كثيرون، وإذا أبوا أن يزوجوا مولى، أو عبدًا منهم يزوجوا من العرب، العرب كثيرون يلتمسوا لها الأخ الطيب، وإذا خطبها الطيب في نفسه، وفي دينه، ولو كان بعيدًا منهم؛ فليزوجوه والحمد لله، ولا يجبرونها على من لا ترضاه من ابن عم، أو ابن خال، أو شيخ كبير لا ترضاه، وهي شابة. الواجب: أن يراعى أمرها، وأن تراعى رغبتها، لا في الفاسدين، لكن في الصالحين، أما أنها تجبر لأجل شهوة وليها؛ لأن وليها هذا نسيبه آخذ بنته، أو آخذ أخته، يجبروها على والد نسيبه، أو أخت نسيبه، أو أخو زوجته .. هذا غلط، هذا ظلم، أو يجبروها على شيخ كبير؛ لأنه يزوجه بنته، أو يزوجه بنته شغارًا، زوجني، وأزوجك، يجبر بنته حتى الذي يزوجه يزوجه بنته، أو أخته، هذا ظلم أيضًا، النبي نهى عن الشغار، وحذر من الشغار -عليه الصلاة والسلام- ولا يجوز أنه يزوج شغارًا يقول: أعطني بنتك، وأعطك بنتي، أعطني أختك، وأعطك أختي، أو أعطني ولدك، وتعطي ولدي، هذا منكر، لا يجوز هذا، ولا يحل.  الواجب على المؤمنين أن يتباعدوا عن هذا الشيء، وأن يزوجوه من غير إجبار للبنات، ولو كانت بنتك لا تجبرها، زوجها من ترضى من الأخيار الطيبين، وليس لك أن تجبرها إذا أبت لا تزوجها حتى يأتيها من ترضاه من المسلمين، ولو جلست إلى أن تشيب، لا يضرك ذلك مادام لم تجبرها فأنت في سلامة، أما أن تجبرها، وتضرها، فلا يجوز لك أبدًا، الحاجة لها.","link":"https://binbaz.org.sa/fatwas/2435/حكم-تزويج-الولي-موليته-لرجل-صالح-لكنه-دونها-في-النسب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_962.mp3","categories":["الخِطْبَة والاختيار ","بر الوالدين"]},{"id":6614,"question":"سبق أن قدمت لسماحتكم سؤالي، وهذا وقد جعلني في قلق، وهو أنني خطبت بنتًا متدينة، ولكن أمي لا تريدها زوجة لي لخلافات عائلية، وقد قلتم سماحتكم إنه لا طاعة لمخلوق في معصية الخالق فما هو صحة حديث ابن عمر أطع أباك هذا السؤال ضروري، ونرجو من سماحتكم الإجابة عليه؟","title":"حكم الزواج بدون رضا الوالدة","answer":"الجواب:  إذا كان أبوك مثل عمر بن الخطاب، وأمك مثل عمر بن الخطاب، المقصود أن النبي ﷺ أمر ابن عمر أن يطيع عمر في امرأة ما تصلح، أما إذا كانت المرأة صالحة، وجيدة، ولكن أمك لشيء بينها وبينها لا تريدها، فإذا استطعت أن تجد غيرها، وتجمع بين المصلحتين -بين أمك وبين المرأة- فهذا أحسن، وأطيب، وإذا لم يتيسر ذلك؛ فأرض والديك بالكلام الطيب، وإذا كانت لا تريدها فاجعلها في مكان آخر، وبيت آخر، وأحسن إلى أمك، وعف نفسك، تزوج حتى تعف نفسك، وتطيع ربك بالزواج، أنت مأمور بالزواج، النبي ﷺ يقول: يا معشر الشباب من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج.  أنت مأمور بطاعة ربك، وطاعة أمك، فعليك أن تبر أمك بالكلام الطيب، والإحسان إليها، والإنفاق عليها -إذا كانت محتاجة- وعليك أن تعف نفسك بالزواج إذا تيسرت المرأة الصالحة المناسبة، وإذا استطعت الجمع بين الأمرين -بين إرضائها وبين وجود المرأة المناسبة- فهذا خير، وإذا كان ما تيسر، ولم يتيسر لك إلا هذه المرأة التي تكرهها بغير حق .. فتزوج، وأرض أمك بالشيء الذي تستطيع من الطرق، وإذا لم تستطع؛ فاجعلها في مكان، وأمك في مكان، واستعن بالله على ذلك، والله يعينك إذا أردت الخير، وصدقت في طلب الخير.","link":"https://binbaz.org.sa/fatwas/2462/حكم-الزواج-بدون-رضا-الوالدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_989.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":6673,"question":"شاب أراد أن يتزوج، ولكن والدته أظهرت له أنها لا ترغب زواجه من تلك المرأة، دون ذكر السبب إلى الكراهية، ثم تكرر هذا من الوالدة مرة ثانية عندما خطب امرأة أخرى، فما هو العمل، علمًا أن الشاب لم يتزوج بعد؟","title":"حكم الزواج بامرأة بخلاف رغبة الأم","answer":"الجواب: عليه أن يحاول مع والدته بيان محاسن المرأة التي تدعو إلى الزواج بها، وبيان حاجته إلى الزواج، وأن يستعين على ذلك بأبيه، أو إخوته، أو غيرهم ممن لهم صلة بوالدته من أخوال، ونحو ذلك؛ حتى ترضى -إن شاء الله- بالزواج، وحتى توافق على المرأة المعينة، ولا يتساهل في هذا شيئًا، بل يجتهد في إقناعها بالأسباب البينة، ويستعين على هذا بمن تقدره والدته من أخوال، أو أعمام، أو أبيه، أو جده، أو غير ذلك من الأقارب، والجيران وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فإنها إذا لم تقنع فما ذاك إلا بأسباب منه هو، أو بسيئة منه، فقد قال الله : وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَنْ كَثِيرٍ[الشورى:30] فليفتش، ولينظر في نفسه، وليتب إلى الله من سيئاته، وتقصيره، وليسأل ربه أن يشرح صدرها لما يريد من الخير، وأن يهديها لقبول ما أراد، هذا كله إذا كانت المخطوبة طيبة في دينها سليمة. أما إذا كانت الوالدة تعرف عنها ما لا ينبغي، وقد نصحت له في منعها من ذلك؛ لأنها تعرفها، وأنها لا تصلح في دينها، أو لأسباب وجيهة؛ فالوالدة تطاع في هذا الأمر، ولا ينبغي لك أن تجد في نفسك عليها؛ لأنها ناصحة، فالوالدة لا تزال ناصحة أبدًا إلا ما شاء الله، وهو قليل، والغالب، على الوالد والوالدة النصيحة، ومحبة الخير للولد، والحرص على ما ينفعه في الدنيا، والآخرة. فاتهم رأيك، وحاسب نفسك، واعلم أن الوالد، أو الوالدة، أو غيرهما إنما يكون منهما ما يعوق عن بعض شأنك؛ لأسباب منك، أو بتقصير منك، أو بجهل منك، فإذا تواصى فيك الاستقامة، والنصح، ومحبة الخير، وأن المخطوبة طيبة، وسليمة، فسوف يهدي الله الوالد، والوالدة لذلك، فعليك بدعاء الله، وأن يهديك صراطه المستقيم، وأن يشرح صدر والديك لما فيه سعادتك، ولما فيه نجاتك، وأبشر بالخير، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].","link":"https://binbaz.org.sa/fatwas/2558/حكم-الزواج-بامراة-بخلاف-رغبة-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1053.mp3","categories":["حكم الزواج وأهميته","بر الوالدين"]},{"id":6915,"question":"الذي يتزوج، ويخرج عن أهله، ما حكمه إذا أرغمته زوجته بالخروج لوحدنا في بيت عن أهلنا، ولم نقطعهما، بل نصلهما كلما غبنا مدة قليلة عنهما، مع ذكر الدليل، شاكرين تجاوبكم، ولكم تحياتنا؟","title":"حكم من تزوج وأراد الخروج عن أهله","answer":"الجواب: إذا خرج الولد عن والديه لأسباب اقتضت ذلك بإذنهما، وسماحهما؛ فلا بأس، إذا سمح الوالدان، وأذنا له في الخروج؛ فلا شيء في هذا؛ لأن المرأة قد لا تناسبهما، وقد لا تستقيم معهما، فإذا سمحا له بالخروج في بيت وحده؛ فلا حرج عليه، ولا بأس عليه، وليس هذا من القطيعة. إنما الكلام فيما إذا لم يسمحا، هذا هو محل البحث، إذا لم يسمحا له بالخروج، ولم تستقمْ الحال بينه وبينهما، هذا هو محل النظر، هل يقطعهما؟ هل يعصيهما؟ هل يطلق المرأة؟ هذا هو محل النظر، أما إذا سمحا، وأذنا له بالخروج؛ فلا شيء عليه، ولكن إذا لم يسمحا؛ فالإنسان ينظر، وليتأمل، فإن كانت المرأة أساءت إليهما، ولم تحسن صحبتهما؛ فهذه لا خير فيها؛ فينبغي إبدالها، وطلاقها، ويعطيه الله خيرًا منها وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2].  أما إذا كانا هما اللذان أساءا إليها، وهي محسنة إليهما، وهي طيبة الدين، والأخلاق، وقائمة بحقهما من الخدمة، وغير ذلك، ولكنهما يبغضانها لأسباب أخرى؛ فهذا هو محل نظر، لا يعجل، يجتهد في ارضائهما، والكلام الطيب معهما، ويبين حال المرأة، وحاجته إليها، وأنها لم تسِئْ إليهما، ولم تقم إلا بالخير، لعل الله يهديهما، فيكفا عن إلزامه بطلاقها، ولا يخرج، ولا يعجل في الخروج، بل يطمئن. والذي يظهر أنها إذا كانت لم تسِئْ؛ لا يلزمه طلاقها؛ لأنهما هما اللذان أساءا إليها، وأساءا إليه، ولكن يرفق بهما، ويجتهد في برهما، والإحسان إليهما، والصبر على ما قد يقع منهما من الأذى حتى يفرج الله، ولا يعجل في الطلاق؛ لأن المرأة الصالحة قل أن يوجد مثلها بعد ذلك. السؤال: وادعت المرأة أنها لا تستريح في العيش مع أمه، ولا بد أن يقيم لها بيتًا خارج القرية؟ الجواب: هذا ينظر فيه، إن سمحا له؛ فلا إشكال، وإذا لم يسمحا له وهما في حاجة إليه؛ فليطلقها، وليصبر معهما؛ حتى يأتي الله بامرأة تصبر عليهما.  أما إذا كان لا يستطيع طلاقها؛ لأنه فقير، وإذا طلقها قد ينضر، وقد يصيبه ضرر عظيم في عدم وجود زوجة، وعدم القدرة على الزوجة؛ فليستسمحهما، ولا يعجل في الأمور، ولعل إخوته يقومون بالواجب، وهو معذور في هذه الحالة؛ لأن الطاعة تكون في المعروف إنما الطاعة في المعروف.  وليس طلاقها -وهي مستقيمة- ليس طلاقها من المعروف إذا كانت طيبة في دينها، وفي أخلاقها، ولم تسِئْ إليهما، ولكن لم تستقم الحال معهما، إما لبخل والديه، وإما لسوء معاملة أولادهما الآخرين، أو بناتهما، أو غير ذلك. إذا كان هناك أسباب أخرى؛ فلا يعجل في الطلاق ما دامت صالحة في نفسها الزوجة، أو كذلك إذا كان عاجزًا عن تحصيل غيرها، فلا يعجل إلا إذا كانت في نفسها سيئة، غير مستقيمة، أو غير مستقيمة معهما، بل تؤذيهما، فإذا كانت غير صالحة في نفسها، أو غير صالحة معهما تؤذيهمان وتسيء خلقها معهماح فليطلقها، وسوف يعطيه الله خيرًا منها وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2].","link":"https://binbaz.org.sa/fatwas/2845/حكم-من-تزوج-واراد-الخروج-عن-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1293.mp3","categories":["الجهاد والسير","بر الوالدين"]},{"id":8167,"question":"الرسالة التالية باعثها أخونا المهندس (س. ط) ويعمل في الكويت، يقول: خطبنا قبل سنة أنا وأخي بنات خالتنا، ولم يكن هناك أي شرط في عقد الزواج، وبعد كتب الكتاب يريد والدها أن نمتنع عن السكن مع أهلنا، مع العلم بأن عائلتنا صغيرة، ويريد كذلك أن نقطع المصروف عن أهلنا، وأن لا نكمل تعليم إخواننا، كما أنه يريد أن نمتنع عن زيارة أعمامنا وخالاتنا وأختنا وجميع الأقارب وأن لا يزورونا كذلك، ولقد أحضرناه للتفاهم بحضرة إمام المسجد إلا أنه تلفظ على والدتنا بكلام بذيء، وتطاول على الله عز وجل، ووسطنا له أكثر من شخص إلا أنه يصر على شروطه، ووالدي ووالدتنا يصران على تطليق البنات، ولا سيما الوالدة، هل نطيع والدتي ونطلق البنات أم ماذا، وما رأي الشرع في ذلك؟ أفيدونا أفادكم الله؟","title":"حكم طاعة الوالدين في طلاق الزوجة","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل فالأولى تطليق البنات ومراعاة خاطر الوالدين، وهذه الشروط شروط قبيحة تفضي إلى قطيعة الرحم وتفضي إلى الشحناء بين الأقارب، وهذا كله ليس بطيب، وعمل أبي البنتين عمل رديء لا ينبغي، فإن وافق على نقل البنتين إلى بيوتكما عند أهلكما فالحمد لله وإلا فطلاقهما أولى، وإذا كانت البنتان ترغبان في النكاح ففي إمكانهما أن يرفعا الأمر إلى المحكمة حتى تحول المحكمة بين والديهما وبين رأيه القبيح، فهذا هو الذي نرى في هذا، المحكمة تنظر في الأمر، فإن لم تريا محاكمته فلا بأس، والتطليق أولى، ولعل الله أن يرزقكما خيراً من هاتين البنتين في الدين والدنيا، أما التسبب في قطيعة أرحامكم وعقوق والديكم فهذا شيء لا ينبغي ولا ينصح به من يخاف الله ويرجوه سبحانه وتعالى.\nوفق الله الجميع وهدى الجميع.","link":"https://binbaz.org.sa/fatwas/5962/حكم-طاعة-الوالدين-في-طلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10404.mp3","categories":["بر الوالدين","المشكلات الزوجية","الحقوق الزوجية"]},{"id":8303,"question":"هذه رسالة من المرسل محمد إمام حسن مصري يعمل بمنطقة الجوف، خلاصة رسالته أنه يقول بأنه يعيش في بلده في أسرة مكونة من الوالدين والإخوة وأبناء له، وهو يعمل هنا وإخوته ووالده يعملون هناك، وله ولدان يدرسان بالثانوية، ووالده يقوم بمصاريف البيت والزرع والأولاد، وهو رجل كبير السن ولم يتعلم ولم يوفر شيئاً لأولاده، فهل يحق لي وأنا هنا وأنا أرسل لهم مبالغ من المال لوالدي، هل يحق لي أن أخفي شيئاً سراً من كسبي احتياطاً لأولادي الذين هم من صلبي أفتوني بارك الله فيكم؟","title":"حكم الإنفاق على الوالدين","answer":"الجواب: الواجب عليك أن تنفق على والدك وعلى أولادك وعلى زوجة والدك بما تستطيع حتى تسد حاجاتهم وما زاد على الحاجة فلك أن تبقيه عندك، ولكن لابد من الإنفاق على والدك وعلى أولادك وعلى زوجة والدك وعلى أولاده أيضاً إذا كان عنده أولاد قاصرون ضعفاء فعليك أن تنفق على الجميع، وهذا من صلة الرحم ومن بر الوالد وهو واجب، أما إن كان والدك غنياً ويستطيع أن ينفق على أولاده وعلى نفسه، فعليك أن تنفق على ولديك اللذين عنده كفايتهما، وتصطلح مع والدك في الشيء الذي يرضيه ولا يلحقك معه حرج في هذا الأمر. نعم.\nالملقي: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6112/حكم-الانفاق-على-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20102.mp3","categories":["النفقات","بر الوالدين"]},{"id":8676,"question":"هذه رسالة وردتنا من العراق من بغداد من المستمعة لقاء محمد لطيف تقول في رسالتها: في حالة إذا ما بعثت الأم ابنها إلى السوق وأوصته بشراء حاجات ما، وأعطته مبلغاً من المال واشترى الابن الحاجات وزاد من المال بعض النقود، فهل حرام عليه أخذ هذا المال دون علمها، مع أنه مال والدته ويحق له كما سمعت من الناس أن يتصرف به أو يأخذ من جيبها مثلاً أو من حقيبتها دون علمها، أفيدوني بارك الله فيكم؟","title":"حكم الأخذ من مال الأب أو الأم بغير إذنهما","answer":"الجواب: ليس له أن يأخذ الفاضل إلا بإذنها فهو وكيل وأمين فعليه أن ينفذ ما قالته والدته أو قاله والده أو غيرهما ممن وكله، وليس له أن يأخذ الفاضل بل عليه أن يرد الفاضل إلى من وكله، سواءً كان الموكل أمه أو أباه أو غيرهما، وليس له أن يأخذ الزيادة، وليس له أن يأخذ من مال أمه إلا بإذنها، ولا من مال أبيه إلا بإذنه، ليس له التصرف في أموالهما إلا بإذنهما، اللهم إلا أن يكون فقيراً وأبوه قصر ولم ينفق عليه وليس له من ينفق عليه سوى أبيه مثلاً، فهذا له أن يأخذ من مال أبيه أو من مال أمه ما قصرا عليه في النفقة، إذا كان في نفقتهما وفي عيالهما وهو عاجز ليس عنده قدرة على التسبب وليس عنده مال، وهو في حضانة أمه أو أبيه، فعليهما أن ينفقا عليه النفقة المعتادة المعروفة في مثل بلدهما أو في أمثالهما، فإذا قصرا عليه فله أن يأخذ من ذلك بالمعروف، يأخذ من مالهما بالمعروف قدر حاجته فقط، أما إذا أرسلاه بمال ليشتري حاجة ليس له أن يأخذ الزيادة بل يرد الزيادة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6816/حكم-الاخذ-من-مال-الاب-او-الام-بغير-اذنهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21503.mp3","categories":["النفقات","بر الوالدين"]},{"id":8885,"question":"الواقع في سؤالها الأخير سماحة الشيخ تذكر بعض المعاناة التي تجدها ولا سيما إذا جاءها أناس زوار في المنزل وهي لا تريد السلام عليهم بأنهم أجانب كما تقول إلا أن أهلها يمقتون فعلها، وترجو التوجيه أيضاً؟","title":"حكم طاعة البنت لأمها في السلام على الأجانب","answer":"الجواب: هذا فيه التفصيل، إن كان القادم نساء فلا مانع من الاتصال بهم، إرضاء للوالدة ونصيحتهم وتوجيههم إلى الخير فهذا من باب الدعوة إلى الله، فلا ينبغي لك أن تمتنعي من هذا، ولعل الله أن يهدي بك هؤلاء فتفلحي وتنجحي في هذا الأمر، أما إن كانوا رجالاً هذا محل تفصيل، إن كان المقصود السلام عليهم لأنهم أقارب أو جيران فلا مانع من السلام عليهم ورد السلام عليهم مع الاحتفاظ بالحجاب الشرعي وعدم إبداء شيء من الزينة أو التبرج، تكونين مستورة في شعورك وبدنك كله ووجهك ونحو ذلك، وتردين السلام والتحية وتسألينهم عن أهليهم لا بأس بهذا، وإذا تمكنت من النصيحة لهم والدعوة إلى الله  فافعلي وهذا لا يضرك.\nأما إن كان الحضور يقتضي المشاركة في محرم أو تبرج بما حرم الله، أو كشف لشيء من العورة أو مشاركة فيما حرم الله من شرب مسكر أو غير هذا مما حرم الله فهذا لا تطيعيهم فيه واعتذري، وقولي: إن هذا لا يجوز لك، وإنك تنصحينهم أن يتركوا ما حرم الله، وأن المشاركة فيما حرم الله أمر لا يجوز، فإن عذروا فالحمد لله، وإن لم يعذروا فأنت معذورة من جهة الله ولا يضرك كيدهم ولا يضرك غضبهم، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/7041/حكم-طاعة-البنت-لامها-في-السلام-على-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13911.mp3","categories":["قضايا المرأة","بر الوالدين","النظر والخلوة والاختلاط"]},{"id":9260,"question":"أخ من جمهورية مصر العربية بعث برسالة يقول المرسل عبدالرحمن مبروك سلامة له مجموعة من الأسئلة، سؤاله الأول يقول: هل يجوز لوالدي أخذ مصاريف زواجي مني وهو في حالة ميسرة وأنا موظف بسيط ليس لي سوى المرتب؟","title":"حكم أخذ الوالد مصاريف ابنه المعدة للزواج","answer":"الجواب: ليس له ذلك ولا يجوز؛ لقول النبي ﷺ: لا ضرر ولا ضرار حتى لو كان محتاجاً ليس له أن يضرك وعليه أن يستعمل أسباباً أخرى كالقرض والتجارة والأسباب التي يستطيعها في جلب المال، أما أن يضرك فليس له ضررك، فلا يأخذ مالك الذي تتزوج به أو تنفقه على أولادك أو على زوجتك ليس له ذلك وإنما عليه أن يطلب سبباً آخر وعملاً آخر.\nفالحاصل أنه مادام بهذه الحال ميسوراً والحمد لله فليس له أن يأخذ المصاريف التي تعدها للزواج أو تعدها لحاجتك وحاجة أهلك. نعم.\nأما الزيادة فلا بأس لو أخذ منك زيادة فيها فضل أو طلب منك ذلك فلا بأس تعطيه ما طلب، يقول النبي ﷺ: إن أطيب ما أكلتم من كسبكم وإن أولادكم من كسبكم لكن ليس له أن يضرك. نعم.\nالمقدم: كأني فهمت من السؤال سماحة الشيخ أن الوالد يريد أخذ المصاريف التي دفعها من أجل زواج ابنه والابن هو السائل؟\nالشيخ: الذي فهمنا من كلامه أنه أعد مصاريف ليتزوج بها فيريد أبوه أن يأخذها هذه المصاريف هذه النقود التي أعدها ليتزوج بها يريد أبوه أن يأخذها لينتفع بها هو ويحول بينه وبين الزواج، هذا الذي فهمنا من سؤاله.\nالمقدم: وإذا كان على الفهم الثاني؟\nالشيخ: الفهم الثاني ما هو؟\nالمقدم: إذا كان الوالد قد دفع مصاريف الابن للزواج ثم أراد من الابن أن يسدد تلك المصاريف؟\nالشيخ: هذا فيه تفصيل، إن كان الابن يستطيع فحق أن يسدد وإن كان فقيراً فليس لأبيه حق في هذا، بل عليه أن يزوجه إذا كان أبوه يستطيع. نعم.","link":"https://binbaz.org.sa/fatwas/7423/حكم-اخذ-الوالد-مصاريف-ابنه-المعدة-للزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15310.mp3","categories":["النفقات","بر الوالدين"]},{"id":9322,"question":"وهذه رسالة وردت إلى البرنامج من السائلة (ب. ع. أ) من السودان، تقول: أنا ربة بيت وزوجي صاحب دكان كان يعطيني قليلاً من السكر لعمل حلوى لأبيعها والعائد من بيعها أدخله في بعض ضروريات المنزل التي يحجم زوجي عن إحضارها، والآن رفض زوجي إعطائي هذا السكر وأنا آخذه بالخفاء، فما الحكم في ذلك؟","title":"حكم أخذ المرأة من مال زوجها للضرورة بدون علمه","answer":"الجواب: لا حرج إذا كان لمصلحة البيت وحاجة البيت المعتادة التي ليس فيها إسراف ولا تبذير فلا بأس، ثبت عن رسول الله ﷺ أن هند بنت عتبة زوجة أبي سفيان بن حرب سألت النبي ﷺ فقالت: يا رسول الله! إن أبا سفيان لا يعطيني من النفقة ما يكفيني ويكفي بني، هل علي جناح إن أخذت من ماله بغير علمه ما يكفيني ويكفي بني؟ فقال النبي ﷺ: لا حرج، خذي من ماله بالمعروف ما يكفيك ويكفي بنيك، فرخص لها النبي ﷺ أن تأخذ من ماله ما يكفيها ويكفي أولادها بالمعروف، يعني: بالمتعارف الذي ليس فيه إسراف ولا تبذير، فإذا أخذت من ماله سكراً أو غيره من النقود لهذه الحاجة، لحاجة البيت وحاجة الأطفال المعتادة فلا حرج في ذلك، ولو بغير علمه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7489/حكم-اخذ-المراة-من-مال-زوجها-للضرورة-بدون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23707.mp3","categories":["النفقات","بر الوالدين"]},{"id":9649,"question":"السؤال الرابع في رسالة الأخ (م. ر عبد الرب ) من عدن يقول فيه:شاب مسلم يريد الزواج من فتاة لا يعلم هي هل تصلي أم لا ؟ هل يجوز ذلك الزواج وما حكم ذلك، أفيدونا أفادكم الله؟","title":"حكم خطبة امرأة لا يُعلم أتصلي أم لا","answer":"الجواب: لابد أن يتثبت في الأمر؛ يسأل عنها أهل الخبرة، فإن الزواج من الكافرة لا يجوز والله يقول سبحانه: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] ومن ترك الصلاة كفر على الصحيح من أقوال العلماء ولو كان مقرًا بالوجوب، إذا تركها تهاونًا وكسلًا كفر كما قال النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.\nفإذا كانت لا تصلي لا يتزوجها، وأما إذا عرف أنها تصلي وجيدة يتزوجها قال النبي ﷺ: تنكح المرأة لأربع لمالها ولجمالها ولحسبها ولدينها فاظفر بذات الدين تربت يداك، فذات الدين مطلوبة ... الصلاة التي هي أعظم الأركان وأهمها بعد الشهادتين. نعم.","link":"https://binbaz.org.sa/fatwas/7815/حكم-خطبة-امراة-لا-يعلم-اتصلي-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19411.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":9650,"question":"تسأل الأخت من مكة أيضاً وتقول: أنا متزوجة من مدة عشر سنوات، وقد حصل بيني في يوم من الأيام وبين زوجي خصام، حيث قال لي: أحضري طعام العشاء فرفضت طاعته، وقلت له: لن أحضر لك الطعام حتى توصلني إلى أهلي، فوقف معي ساعتين ثم اتجه إلى منطقة أخرى ولم يقل لي أي شيء، فهل هو آثم وأنا آثمة في عدم طاعته، أم لا، أفيدوني وماذا أفعل حتى أرضي زوجي وفقكم الله؟","title":"رفضت طاعة زوجها وتخاف من الإثم","answer":"الجواب: الواجب على المرأة السمع والطاعة لزوجها في المعروف، وإحسان الخلق، وطيب الكلام، وتنفيذ الأوامر من إحضار الطعام أو غيره من الشاي أو القهوة أو حاجات أخرى مما أباح الله، هذا هو الواجب على الزوجة، والواجب على الزوج كذلك أن يعاشرها بالمعروف بالكلام الطيب، بالسيرة الحميدة، كما قال الله سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وقال الله : وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] فحق الزوج أكبر وهي لها حق عليه أن يعاشرها بالمعروف بالكلام الطيب، بالسيرة الحميدة، بالإنفاق عليها نفقة أمثالها، كسوتها كسوة أمثالها، يخاطبها بالكلام الطيب لا بالسب واللعن، بل بالكلام الطيب والأسلوب الحسن، وهي كذلك تخاطبه بالكلام الطيب والأسلوب الحسن، وتسمع وتطيع في أوامره، لا تعصيه في الأوامر التي ليس فيها حرج شرعاً، ليس فيها منكر، كإحضار الطعام، إحضار الشاي، عمل شيء آخر مما أباح الله مما جرت به العادة، أن تفعله الزوجة مع زوجها، هذا هو الواجب على المرأة حتى تستقيم الأحوال، وحتى تستمر العشرة الطيبة.\nأما إذا أمرها بما لا يجوز كأن يقول لها: تحضر له الخمر أو الدخان أو ما أشبهه مما حرم الله، أو تسمع معه الأغاني والملاهي لا يلزمها ذلك؛ لأن الله يقول جل وعلا: وَلا يَعْصِينَكَ فِي مَعْرُوفٍ [الممتحنة:12] ويقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فإذا أمرها بالمعصية ليس لها أن تطيعه، ولكن ترد عليه بالرد الطيب: يا فلان! هذا لا يجوز، هداك الله، أعاذك الله من الشيطان، هذا أمر لا يجوز لي ولا لك، وليس لي أن أعينك على ما حرم الله، يكون عندها أسلوب حسن تعضه وتذكره بالله عز وجل، ولكن لا تطيعه في المعاصي، وعليها أن تخدمه الخدمة المعروفة المعتادة بين أمثالهم؛ لأن الأسر تختلف فإذا كان مثلها يخدم مثله والعادة أنها تخدمه في الأسر المماثلة لهم في بلادهم فإنها تخدمه.\nأما إذا كانت من أسرة تخدم فإن عليه أن يخدمها إذا استطاع ذلك عليه أن يخدمها عملاً بالعادة المعروفة؛ لأن الشرط العرفي كالنطقي ولكن إذا تسامحت وخدمت كما خدمت فاطمة رضي الله عنها بنت النبي ﷺ زوجها علي ، كانت تطحن وتخدم وتصلح الطعام رضي الله عنها وأرضاها، فهكذا ينبغي للزوجة أن تتسامح وأن تخدم حتى ولو كان مثلها يخدم إذا تنازلت وتسامحت كان هذا من طيب الأخلاق ومن حسن السيرة، ومن أسباب استمرار العشرة، لكن إذا كان مثلها يخدم وأسرة تخدم وتيسر للزوج أن يخدمها فذلك حق. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7821/رفضت-طاعة-زوجها-وتخاف-من-الاثم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25106.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":9825,"question":"هو أضاف أخيراً ويقول: أنا خرجت من البيت الخاص والذي خلفه والدي، وتسكن فيه والدتي وسكنت في بيت بعيد عن والدتي تلافياً للمشاكل، فهل علي إثم في خروجي هذا؟","title":"حكم مفارقة الأم في السكن","answer":"الجواب: إذا كانت الوالدة سمحت بذلك فليس عليك إثم، أما إذا كانت الوالدة غير سامحة وهي في حاجة إليك فالواجب عليك أن ترجع إليها وأن تبقى معها، لقضاء حوائجها وإيناسها والحرص على برها، فإن برها من أهم المهمات ومن أعظم الواجبات.\nأما إذا سمحت عنك فلا بأس.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7990/حكم-مفارقة-الام-في-السكن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26011.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":9886,"question":"يسأل أيضاً ويقول: هل على الزوجة خدمة أم زوجها أم لا؟ وما الحكم في ذلك؛ لأن هذا سبب مشكلة عندنا في البيت، ويجعلني أحياناً ألجأ إلى التفكير في الطلاق، وقد سألت في بلدتي مصر أحد المشايخ فقال: حاول أن توفق بين أمك وزوجتك، علماً بأن الزوجة يتيمة وليس لها أحد سواي، ولي منها أبناء ووالدتي ليست كبيرة السن ولله الحمد وعندها بنات في المنزل، والتوفيق بينهما أصبح مستحيلاً، فهل يجوز لي أن أعمل لي بيتاً مستقلاً لي وزوجتي وأترك والدتي وإخوتي، ما الحكم في ذلك؟ بارك الله فيكم.","title":"هل على الزوجة خدمة أم زوجها؟","answer":"الجواب: خدمة المرأة لزوجها وأهل زوجها أمر يختلف بحسب العرف في البلاد، وكان أزواج النبي ﷺ يخدمن بيوتهن، وكانت فاطمة رضي الله عنها تخدم بيتها، في الطحن والعجن والخبز وغير ذلك؛ وكنس البيت ونحو ذلك. فالذي ينبغي للمرأة أن تخدم زوجها وتخدم البيت، وإذا كان في البيت أمه أو أخته أو بناته، فالمشروع لها أن تخدمهن إذا كان العرف في بلادها كذلك.\nأما إذا كان العرف في الأسرة أو في البلد أو في القبيلة التي هي فيها، أنها تخدم وأنها لا تقوم بالخدمة هي، بل يستجلب لها خادمة، فإنه لا يلزمها وعلى الزوج إذا استطاع أن يأتي بالخادمة إلا أن تسمح بالخدمة، وتقوم بها من غير جبر لها فقد أحسنت في ذلك.\nفالحاصل: أن هذا الأمر يختلف ويتنوع بحسب عرف البلاد، إذا حصلت المشاحة والمشاقة، والأفضل للزوج أن يتحرى في هذا الأسلوب الحسن، وأن يرضي المرأة بما يستطيع من المال عند وجود النزاع حتى تخدم بنفس طيبة، حتى تخدم أمه، تخدم بناته أخواته الصغار، ونحو ذلك يكون بالأسلوب الحسن والكلام الطيب، والمساعدة المالية إذا حصلت المشاقة ولم يتضح العرف الذي يقنعها بأن تقوم بالخدمة في بيتها، والله ولي التوفيق. نعم.\nالمقدم: أثابكم الله وبارك الله فيكم، ولكن إذا استطاع أن يرضي والدته وينتقل في بيت مستقل لا حرج عليه؟\nالشيخ: لا حرج عليه، إلا أن تأبى والدته، إذا كانت الوالدة تأبى أن يخرج؛ لأنها محتاجة إليه أو لأسباب أخرى فلا ينبغي الخروج؛ لأن برها واجب، طاعتها مهمة، وقد يكون إخوته الذين في البيت لا يقومون مقامه، ولا يسدون مسده.\nفالحاصل: أنه ينبغي له أن يلاحظ أمه، ويستشيرها، فإذا سمحت فلا مانع من خروجه في بيت مستقل.\nأما إن كانت محتاجة إليه، أو كان هناك أسباب تدعو إلى عدم سماحها بخروجه فلا يخرج، بل يصبر ويحاول التوفيق بينها وبين زوجته ويرضي الزوجة بما يستطيع ولو بالمال حتى تمشي الأمور على الوجه المطلوب وحتى لا يخسر أمه بسبب زعلها عليه وغضبها عليه، والله المستعان.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8045/هل-على-الزوجة-خدمة-ام-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26402.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":9953,"question":"يسأل أيضاً ويقول: يحصل أحيانًا بعض الخلافات والمناقشة الحارة بين الزوجين فتغضب الزوجةُ زوجها، وهذه المناقشة غالباً ما تكون في أمور دنيوية، فهل تأثم المرأة بإغضاب زوجها؟ أفيدونا أفادكم الله.","title":"هل تأثم المرأة بإغضاب زوجها أثناء النقاش بينهما","answer":"الجواب: إذا كان إغضابها له بغير حق تأثم ولا يجوز لها أن تنازع ولا أن تؤذيه بالكلام، أما إن كان بحق بأن أنكرت عليه منكر، يتساهل في الصلاة فأنكرت عليه، يشرب المسكر فأنكرت عليه وناصحته فغضب فهي مأجورة غير مأزورة بل مشكورة.\nفالمقصود إن كان إغضابها له بحق فهي مأجورة وإن كان بغير حق فهي آثمة ولا يجوز لها إغضابه بدون حق، وعليها الكلام الطيب والسمع والطاعة في المعروف، لكن إذا كان هو يتعاطى المعاصي فأنكرت عليه ونصحته ووجهته إلى الخير فالواجب عليه أن يقبل منها وأن يشكرها وأن لا يغضب لأنها محسنة ومأجورة وناصحة فجزاؤها أن يزداد حبها وأن يشكرها على ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8121/هل-تاثم-المراة-باغضاب-زوجها-اثناء-النقاش-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27407.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":10258,"question":"رسالة من المنطقة الشرقية في المملكة بعث بها أحد الإخوة يقول: المتعاقد طبيب (أ. ل. ح. د): أخونا له قضية مع زوجته يذكر أولاً: أنه على خلاف دائم معها، لأسباب يصفها بأنها تافهة في كثير من الأحيان؟","title":"الخلافات الدائمة بين الزوجين ووسائل تلافيها","answer":"الجواب: ننصحهما بالحلم والرفق والتواصي بالحق والصبر وعدم النزاع وعدم الطلاق، نوصي الجميع بالتعاون على الخير والتواصي بالخير، وعدم المنازعة، نوصي المرأة بالسمع والطاعة لزوجها في المعروف، نوصي الزوج بالصبر والحلم وعدم العجلة في الطلاق أو الضرب أو السب، كل واحد منهما عليه أن يتحمل ويستعمل الرفق في كل الأمور، لقوله ﷺ: إن الرفق لا يكون في شيء إلا زانه، ولا ينزع من شيء إلا شان ، ولأن هذا العمل داخل في وقوله تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228].\nفالمشاجرة الدائمة والنزاع من أسباب الطلاق، وهكذا السب والشتم، فالواجب على كل منهما حفظ اللسان عما لا ينبغي، وحفظ الجوارح عما لاينبغي، والرفق بالأمور والحلم والصبر. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8428/الخلافات-الداىمة-بين-الزوجين-ووساىل-تلافيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27908.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":10260,"question":"يقول: إنها لا تنفق من راتبها إلا النصف والنصف الآخر تضعه في البنك؟","title":"حكم نفقة الزوجة على زوجها","answer":"","link":"https://binbaz.org.sa/fatwas/8431/حكم-نفقة-الزوجة-على-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27910.mp3","categories":["النفقات","بر الوالدين"]},{"id":10559,"question":"سماحة الشيخ! ما الحكم إذا كان الشخص يأكل حراماً وله أبناء وله أناس يعولهم، كيف يتصرفون والحالة هذه؟","title":"حكم إعالة الأبناء والزوجة من مال حرام","answer":"الجواب: الحال فيهم مختلفة، المضطر نرجو أن لا يكون عليه شيء كالصبيان الصغار وأشباههم لأنهم هو الذي يعولهم فالإثم عليه. وأما الزوجة التي تعلم هذا فلها أن تطلب الطلاق وتفارقه؛ لأن هذا عذر لها شرعي، إذا كان كسبه خبيث فلها العذر أن تطلب الطلاق وأن تذهب إلى بيت أهلها وتطالب بتغيير الكسب أو بالطلاق حتى لا تبقى مع من يأكل الحرام.\nأما إذا كان عنده كسب طيب ولكن في ماله اختلاط في ماله شيء من الشبهة فهذا أسهل والأمر فيه أوسع، أما إذا كان معروفاً بالكسب الخبيث وأن كسبه كله خبيث هذا لزوجته العذر ولأولاده العذر في أن لا يأكلوا من بيته كذلك الكبار المشردين العارفين، وأما المضطرون من أولاده الصغار والفقراء لا حيلة لهم فنرجو أن يعفو الله عنهم إذا أكلوا من ماله عند الضرورة، حتى يجعل الله لهم فرجاً ومخرجا.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8733/حكم-اعالة-الابناء-والزوجة-من-مال-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32203.mp3","categories":["النفقات","بر الوالدين"]},{"id":10626,"question":"المستمع (ع. محمد .ع) سوداني مقيم في الدوادمي، بعث بسؤال طويل، ملخصه: إذا احتاج الابن إلى شيء من المال وطلب أباه فلم يجبه إلى طلبه؛ فاضطر الابن إلى السرقة من مال أبيه دون أن يعلم الأب، هل على الابن إثم؟","title":"حكم أخذ الولد من مال أبيه دون علمه","answer":"الجواب: هذا فيه تفصيل: إن كان الأب قصر في النفقة والولد ضعيف ما يستطيع العمل عاجز، فإنه يأخذ من مال أبيه ما يسد حاجته، ولو بغير علمه، وهكذا الزوجة تأخذ من مال زوجها بغير علمه ما يسد حاجتها وحاجة أطفالها؛ لما ثبت في الصحيحين عن عائشة رضي الله عنها أن هند بنت عتبة رضي الله عنها زوجة أبي سفيان قالت: يا رسول الله! إن أبا سفيان رجل شحيح، -يعني: بخيل- لا يعطيني ما يكفيني ويكفي بني إلا ما أخذته من ماله بغير علمه، فهل علي في ذلك من جناح؟ فقال النبي ﷺ: خذي من ماله بالمعروف ما يكفيك ويكفي بنيك فرخص لها أن تأخذ من ماله بالمعروف ما يكفيها ويكفي أولادها.\nفهكذا الولد إذا كان قاصر يدرس ضعيف ما عنده شيء يقوم بحاله وأخذ من مال أبيه كسوة له أو غداء أو عشاء يسد حاجته فلا حرج عليه، أو كان أبوه موسراً والولد ليس عنده شيء وهو في حاجة إلى الزواج، وأخذ من مال أبيه ما يتزوج به؛ لأنه عاجز وأبوه قادر وعنده مال كثير فلا حرج عليه، فإن الواجب على الأب أن يعف ولده بتزويجه. نعم.\nالمقدم: جزاكم الله خيراً، وهذا واجب على الأب سماحة الشيخ؟\nالشيخ: نعم إذا كان قادراً والولد عاجز، أما إذا كان الولد قادراً فليس له أن يأخذ من مال أبيه شيء، بل عليه أن يأخذ من ماله، وينفق من ماله. نعم.\nالمقدم: بارك الله فيكم، والزواج؟\nالشيخ: والزواج كذلك، يتزوج من ماله، إذا كان قادر يتزوج من ماله.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8814/حكم-اخذ-الولد-من-مال-ابيه-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_328/32816.mp3","categories":["النفقات","بر الوالدين"]},{"id":10690,"question":"هل يجوز الكذب على الوالد إذا عمل الولد عملاً غير مرضٍ؛ خوفاً من ضربه، أو التكلم عليه بكلام يكرهه؟","title":"حكم الكذب على الوالد خوف العقوبة إن صدق","answer":"الجواب: إذا كان الكذب لا يضر أحداً، إنما يخلصه من غضب أبيه ولا يضر أحداً فلا بأس بذلك، كأن يقول: ما ذهبت المحل الفلاني، ولا كلمت فلاناً، وذلك لا يضر أحداً، فلا بأس. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8870/حكم-الكذب-على-الوالد-خوف-العقوبة-ان-صدق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33020.mp3","categories":["النفقات","بر الوالدين"]},{"id":10961,"question":"يسأل أخونا أيضًا سؤالًا آخر ويقول: على حياة والدي -رحمه الله- وعندما كنت صغيرًا لم أتجاوز الرابعة عشرة من عمري، كنت أغضبه، ولم أكن أستمع لكلامه، فهل يعتبر هذا عقوقًا؟ وهل عليَّ كفارة؟ لأنني أخشى أن يكون توفي وهو غاضب علي، أرجو الإفادة جزاكم الله خيرًا.","title":"هل يؤاخذ الأبن على عصيانه لوالديه قبل بلوغه للحلم.","answer":"الجواب:  نعم هذا من العقوق إلا إذا أمرك بشيء لا يجوز شرعًا فخالفته، ليس هذا من العقوق؛ لأن الطاعة في المعروف لا في المعصية، فإذا عصيت والدك في المعروف هذا عقوق، وإذا أمرك بالصلاة، ولم تصل فهو عقوق، وإذا أمرك ببر والدتك وأبيت فهذا عقوق، وإذا نهاك عن سب الناس، وعن ظلم الناس وأبيت هذا عقوق ومعصية أيضًا لله . فالخلاصة أنه إذا أمرك بما ينفعك، ونهاك عن ما يضرك، أو أمرك بما ينفعك ولا مشقة عليك، بل تستطيع ذلك، فمخالفته عقوق، وسبه عقوق. أما إذا كان ذلك في معاصي الله فإنه لا يجوز لك أن تطيعه في معاصي الله، إذا قال لك: لا تصل في الجماعة ما يلزمك طاعته، أو قال لك: اشرب الخمر، ما يلزمك طاعته، أو قال لك: استعمل الدخان ليس لك طاعته بهذا؛ لقول النبي ﷺ: إنما الطاعة في المعروف وقوله -عليه الصلاة والسلام-: لا طاعة لمخلوق في معصية الخالق. وعليك أن تستغفر الله، وتتوب إليه مما قصرت في حق والدك، وإذا كنت لم تبلغ الحلم فالأمر أسهل، إذا كنت حين معصيتك له صغير، لم تبلغ الحلم، فالأمر أسهل، ولكن مع هذا كله تدعو له كثيرًا تستغفر له كثيرًا، وتتصدق عليه إذا استطعت، وتستغفر الله من تقصيرك؛ لأنك قد تكون تساهلت في ذلك بعد الحلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9141/هل-يواخذ-الابن-على-عصيانه-لوالديه-قبل-بلوغه-للحلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_364/36408.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":11038,"question":"السائل: أحمد إبراهيم يقول: ما حكم من كان له ابن معوق، وتصرف له مساعدة سنوية من الحكومة، فهل مطلوب منه أن يجعلها للطفل المعوق فقط، أو يجمعها ويشتري له شيئًا يخصه عن إخوته، أم يحق للوالدين ولبقية الإخوة الانتفاع بها سماحة الشيخ؟","title":"حكم تصرف الوالد في مال ولده","answer":"الجواب:  والده مخير، إن شاء حفظها، وإن شاء أنفقها عليه، أو أكلها الوالد؛ لأن الوالد: أنت ومالك لأبيك فإن شاء أنفق عليه من ماله، وإن شاء أنفق عليه مما قررته الحكومة له، وإن شاء حفظه له، كل ذلك إلى الوالد، لا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/9216/حكم-تصرف-الوالد-في-مال-ولده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28720.mp3","categories":["النفقات","بر الوالدين"]},{"id":11051,"question":"هذا السائل أرسل بهذه الرسالة جابر من محايل عسير يقول: لي أولاد كبار وأنا رجل مسن، وهؤلاء الأولاد لا يعملون، ولم أقم بالتقصير عليهم في تربيتهم، وعندما أصبحت مسنًا فروا مني، وعندما أطلب منهم المساعدة لا يقومون بمساعدتي، وهناك شخص آخر من الأولاد يستلم راتبًا، وما زال يطلب مني الزواج بإلحاح، وأنا فقير، علمًا بأنه لا يقوم بمساعدتي وجهوني سماحة الشيخ.","title":"حكم رفض الأبناء النفقة على والدهم المعسر","answer":"الجواب:  الواجب عليهم أن يتقوا الله، وأن يساعدوك، وأن ينفقوا عليك ما دمت في حاجة، هذا هو الواجب عليهم إذا كان عندهم قدرة، فالواجب عليهم أن ينفقوا عليك حاجتك، وهكذا الولد الآخر يجب عليه أيضًا أن ينفق حسب طاقته، وليس عليك تزويجه لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] لكن لو كنت قادرًا وهو عاجز يلزمك التزويج، لو كنت قادرًا وهو عاجز، أما الآن ما دمت عاجزًا فليس عليك شيء، وعليه أن ينفق عليك مع إخوانه، ينفق عليك حاجتك كما أن إخوانه كذلك يلزمهم، حسب طاقتهم أن ينفقوا عليك؛ لأن الله -جل وعلا- أوجب صلة الرحم، وبر الوالدين، ومن أعظم البر أن ينفقوا على والدهم إذا احتاج إليهم، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9229/حكم-رفض-الابناء-النفقة-على-والدهم-المعسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28807.mp3","categories":["النفقات","بر الوالدين"]},{"id":11180,"question":"من جدة رسالة بتوقيع أحد الإخوة يقول: أخوكم في الله سعد، الأخ سعد يقول: الزوجة التي لا تصلي ليس بإرادتها؛ بل بسبب الوساوس، هل يجوز لزوجها معاشرتها وأن تبقى معه، فهي لا تستطيع الوضوء ولا حتى التيمم لمرضها كما قلت: بالوسواس، هل تصلي بدون وضوء؟","title":"كيفية العمل مع الزوجة التي لا تصلي بسبب الوساوس","answer":"الجواب: الواجب تعليمها وتوجيهها، وأن الوساوس التي تعتريها لا يجوز لها أن تميل إليها وأن تستعملها حتى تضيع الصلاة، بل يجب أن تدعها وأن تصلي، وعليك أن توضح لها ذلك وأن تأمرها بذلك، ولو بالتأديب ولو بالضرب المناسب غير المبرح؛ لأن ترك الصلاة كفر أكبر، فلابد أن تعتني بهذا الأمر وأن تلزمها بالصلاة وأن توجهها إلى الخير؛ حتى تدع الوساوس وحتى تصلي الصلاة التي فرض الله عليها، هذا يحتاج إلى جهاد وصبر لابد؛ لأن الجهل داء عضال. فلابد من التعليم والتوجيه والإرشاد منك ومن أمها وأبيها إن كان لها أبوان من أقاربها، لابد من التعاون على البر والتقوى حتى تفهم الأمر الشرعي. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9369/كيفية-العمل-مع-الزوجة-التي-لا-تصلي-بسبب-الوساوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37214.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":11269,"question":"هل يجب على الأبناء إعطاء والدهم رواتبهم الشهرية إذا كان الابن بحاجة للمال ووالده مقتدر ماليًا؟","title":"حكم إلزام الوالد المقتدر ولده المحتاج بإعطاء مرتبه الشهري","answer":"الجواب: لا يلزم الأولاد أن يعطوا رواتبهم آباهم إذا كانوا في حاجة إليها، إنما يعطى من الفضل؛ لقول النبي ﷺ: لا ضرر ولا ضرار وقوله ﷺ: ابدأ بنفسك ثم من تعول فالإنسان يبدأ بنفسه وأهل بيته زوجته وأولاده، فإذا فضل شيئًا وأعطى والده فلا بأس، أما إن كان والده فقيرًا عليه أن ينفق عليه، يلزمه أن ينفق على والده مع أولاده، أما أن يعطيه وهو غير محتاج فلا لا يلزمه ذلك، إلا بعد فضل ذلك عن الحاجة الضرورية، ولهذا يقول ﷺ: ابدأ بنفسك ثم من تعول، ويقول في الحديث الآخر: لا ضرر ولا ضرار، فليس للأب أن يضار ولده والجد كذلك، ولكن الولد يعطي أباه ويعطي جده مما يسر الله فاضلًا عما يلزمه، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9458/حكم-الزام-الوالد-المقتدر-ولده-المحتاج-باعطاء-مرتبه-الشهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37509.mp3","categories":["النفقات","بر الوالدين"]},{"id":11282,"question":"يسأل سؤالًا آخر فيقول: أريد الزواج من إحدى الأسر، لكن جدي منع أولاده وبناته من الزواج من هؤلاء بحجة وجود خلافات قديمة، ما حكم الشرع في ذلك؟","title":"حكم طاعة الجد في عدم الزواج من أسرة معينة","answer":"الجواب:  الأولى لك أن تدعهم لأن الجد أب وبره مطلوب، ولعل في ذلك خيرًا للجميع، فالناس كثير والنساء كثير والحمد لله. فالمشروع لك والأفضل لك فيما أرى التماس جماعة آخرين غير الجماعة التي لا يرضاها جدك لأسباب أشرت إليها، أما تحريم ذلك فهو محل نظر، لكن كونك تتركهم وتراعي خاطر جدك لأنه أب، الجد أب والبر واجب، ولعل في تركهم مصلحة بينة للجميع، هذا لعله أحوط وأولى إن شاء الله. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9451/حكم-طاعة-الجد-في-عدم-الزواج-من-اسرة-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37502.mp3","categories":["الخِطْبَة والاختيار ","بر الوالدين"]},{"id":11286,"question":"يقول: لي أولاد في المدرسة منهم الكبير ومنهم الصغير، وعندما أمنحهم بعض النفقات الشخصية أفضل الكبير على الصغير، فهل هذا جائز؟","title":"حكم إعطاء الوالد لولده الكبير نفقة أكثر من الصغير","answer":"الجواب:  على حسب مصروف المدرسة مثلًاإذا كان حاجة الكبير أكثر يعطى قدر حاجته لا لأجل ذاته، بل يعطى ما يحتاجه في التعلم لأن نفقة الكبير قد تكون أكثر فيما يحتاجه من دفاتر أو كتب أو غير ذلك. فالحاصل: أنه يعطى قدر حاجته في التعليم وإن كان أكثر من الصغير. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9467/حكم-اعطاء-الوالد-لولده-الكبير-نفقة-اكثر-من-الصغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37518.mp3","categories":["النفقات","بر الوالدين"]},{"id":11316,"question":"يقول: هل من حق الفتى أن يختار شريكة حياته بنفسه أم والداه هما اللذان يجبرانه على أن يأخذ فتاة معينة، فمثلًا والدي يصر على أن يزوجني من ابنة عمي وليس لي رغبة فيها، هل عدم طاعة الوالدين في هذه الحالة تعتبر من العقوق؟ جزاكم الله خيرًا، وصاحب هذه الرسالة هو المستمع (ف. ع. ق) من مصر ... ؟","title":"حكم طاعة الولد والديه في الزواج ممن لا يرغب","answer":"الجواب:  لا يلزمك؛ لأن النكاح أمره عظيم، فإذا كانت المرأة لا تناسبك فإنه لا يلزمك إنما الطاعة في المعروف. لكن تستسمح والديك بالكلام الطيب والأسلوب الحسن حتى تلتمس أنت ووالداك امرأة تناسبك، فإن الزواج من امرأة لا تناسبك ولا تريدها يضر ولا ينفع خسارة. فالواجب على والديك ألا يجبراك على امرأة لا تريدها، والواجب عليك أن تستسمحهما وتستعمل معهما الرفق بالكلام الطيب حتى لا يقع بينك وبينهما شيء من العقوق والفرقة والاختلاف، نعم.  المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9495/حكم-طاعة-الولد-والديه-في-الزواج-ممن-لا-يرغب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37706.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":11607,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع أحمد منصور محمد عسيري، الأخ أحمد له قضية مطولة بعض الشيء، ملخصها أنه تزوج، وكلفه ذلكم الزواج مبالغ كبيرة، وحينئذٍ احتاج إلى والده ليعينه على تكاليف الحياة الزوجية، وعلى العيش مع زوجته، إلا أن والده أعرض عنه، ولم يعنه بشيء، وحينئذ يرجو من سماحتكم التوجيه له ولأمثاله، جزاكم الله خيرًا.","title":"حكم إعانة الأب لابنه على الزواج","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أن التزوج من أهم المهمات، ومن السنن المشروعة وقد يجب مع القدرة، لقول النبي -عليه الصلاة والسلام-: يا معشر الشباب! من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع؛ فعليه بالصوم؛ فإنه له وجاء. هذا الحديث يدل على وجوب التزوج مع القدرة، لما في ذلك من المصالح العظيمة من إحصان الرجل، وحمايته من أسباب الفتنة، ولما يترتب عليه من الذرية، وتكثير الأمة، فإذا كان الرجل لا يستطيع، وأبوه يستطيع؛ وجب على أبيه أن يزوجه؛ لأن نفقة الزواج مثل نفقة الأكل والشرب والكسوة، يجب على الوالد أن ينفق على أولاده ما يحتاجون إليه، من طعام وكسوة، كما يجب عليه أيضًا أن ينفق عليهم مؤونة الزواج؛ لأن كل إنسان في حاجة إلى ذلك، إذا استطاع ذلك. أما إذا لم يستطع فهو معذور فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فالذي أنصح به جميع المسلمين أن يجتهدوا في تزويج أبنائهم وبناتهم، وأن يساعدوا في ذلك؛ حرصًا على عفتهم، وبعدهم عن الشر، وعملًا بالنصوص الدالة على ذلك، كقوله سبحانه في كتابه العظيم: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32] وقوله -جل وعلا-: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ [النساء:3] ولهذا الحديث قوله ﷺ: يا معشر الشباب من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج الحديث، وقوله ﷺ: تزوجوا الولود الودود؛ فإني مكاثر بكم الأمم يوم القيامة. فالواجب على الآباء أن يزوجوا أولادهم العاجزين إذا كان الوالد يستطيع تزويج ولده، وعليه أيضًا أن يسعى في تزويج البنت، ويحرص، وهكذا الأخت إذا لم يكن لها والد، يحرص أخوها على تزويجها إذا خطبها الكفء، ولا يفعل ما يعرقل الزواج بغير وجه شرعي؛ لأن في الحرص على تزويج البنين والبنات إعانة لهم على الخير، وعلى العفة عن أسباب الشر، فالواجب على الجميع التعاون في ذلك الرجال والنساء. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذا كان هذا الابن له دخل، ولكنه فرط في دخله، وعبث به هنا وهناك، هل على الوالد إذًا.. الشيخ: المعتبر حال الزواج، إذا كان حال الزواج عنده قدرة لا يجب على الوالد إعطاؤه في ذلك شيئًا، إلا إذا أعطى إخوته مثله، أما إذا كان الولد عنده أموال يستطيع بها الزواج فإنه لا يلزم الوالد أن يساعده في ذلك، كون الولد قد يكون عنده شيء من السفه، وقد فرط في بعض الأموال، العبرة بحال النكاح، والتفريط السابق لا يمنع من المساعدة.","link":"https://binbaz.org.sa/fatwas/9790/حكم-اعانة-الاب-لابنه-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38801.mp3","categories":["النفقات","بر الوالدين"]},{"id":11854,"question":"مستمع أو مستمعة الرمز (ع. هـ. ح. ك)، بل شاب يقول: أنا شاب، ولله الحمد ملتزم بدين الله تعالى، وأعيش في أسرتي المكونة من الوالدة والوالد وإخواني، ولنا أقارب في نفس المكان الذي نحن فيه، ولكن هؤلاء الأقارب وأسرتي في خصام، وقتال دائم، والكل منهم لا يرضى عن الآخر، مع العلم بأن هؤلاء الأقارب على أخلاق سيئة، ومعاملتهم معنا سيئة، وأنا أقف حيران إذا ذهبت إليهم؛ لأصل ما أمر الله بوصله من صلة الرحم، غضب الوالد والوالدة، وإذا لم أذهب حتى أرضي والدي ووالدتي أخشى من عقوبة قطيعة الرحم، فبماذا توجهونني؟ جزاكم الله خيرًا.","title":"حكم طاعة الوالدين في عدم صلة الأرحام","answer":"الجواب:  إذا كان الأقارب عندهم منكرات ظاهرة يستحقون عليها الهجر؛ فلا تذهب إليهم، لكن لو ذهبت إليهم للنصيحة والتوجيه إلى الخير، والأمر بالمعروف، والنهي عن المنكر؛ فهذا طيب، لعلهم يهتدون، ولو ما أعلمت والديك، فإذا لم تجد النصيحة، ولم ينفع فيهم التوجيه؛ فحينئذٍ يشرع هجرهم؛ لإصرارهم على المعصية، ومع ذلك ترضي والديك بهذا الأمر. أما إذا رجوت أن الله ينفعهم بنصيحتك وتوجيهك؛ فاذهب إليهم، وانصحهم، وأمرهم بالمعروف، وانههم عن المنكر؛ لعل الله يهديهم بذلك، ولو لم يرض والداك لكن إذا تيسر إخفاء ذلك عن والديك، تجمع بين المصلحتين؛ فحسن، يقول النبي ﷺ: إنما الطاعة في المعروف فإذا ذهبت إلى أقاربك للنصح والتوجيه والأمر بالمعروف والنهي عن المنكر؛ هذا عمل طيب، ومشروع ولو لم يرض والداك، لكن إذا تيسر أن تخفي ذلك عنهما، فتجمع بين المصلحتين: بين إرضاء والديك، وبين القيام بما شرع الله لك من النصيحة والتوجيه، فهذا كله حسن، نعم.","link":"https://binbaz.org.sa/fatwas/10052/حكم-طاعة-الوالدين-في-عدم-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39715.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":11934,"question":"إذا اشترى لنا والدي بعض الأشياء للبيت، ووالدتي ولِيَّةُ ذلك، فأخذنا منه أنا وإخوتي بدون علم منها، فما حكم ذلك؟","title":"حكم أخذ شيء من حاجات البيت بدون إذن الأب","answer":"الجواب:  إذا كنتم في بيوت مستقلة؛ فليس لكم الأخذ إلا بإذن الوالد؛ لأنه اشترى لبيته، والوالدة لا تعطيكم شيئًا إلا بإذنه، إلا إذا كنتم تعلمون أنه يسمح، وليس عنده في هذا مانع؛ فلا بأس، فإذا اشترى لحمة لبيته؛ لا تأخذوا منها شيئًا، أو فاكهة للبيت؛ لا تأخذوا إلا بإذنه، النطقي، أو العرفي إذا كان من عرفكم المعروف بينكم أنه يتسامح، وأنه لا يهمه هذا الأمر؛ فلا بأس، وإلا فليس لكم الإقدام على هذا الشيء الذي اشتراه لبيته، وعند زوجته، أو عائلته الصغار، وأنتم في بيوت مستقلة، لا تأخذوا منه شيئًا إلا بإذنه. والوالدة كذلك لا تعطيكم إلا بإذنه، إلا إذا كان هناك إذن معروف من والدكم، إذن صريح، أو تدل عليه شواهد الحال، ومعروف من حالته وسماحه، وأنه لا يأبى أن يؤخذ من هذا الشيء، إذا عرف هذا؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10118/حكم-اخذ-شيء-من-حاجات-البيت-بدون-اذن-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42711.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":11941,"question":"له قضية أخرى سماحة الشيخ يقول فيها: كما سبق وذكرت أنني استقلت من العمل، ومريض، وليس لي دخل، ولي أسرة كبيرة، وعندما أطلب المساعدة من والدي وإخوتي يرفضون مساعدتي، ويقولون: ليس لك حق علينا في مساعدتك، رغم أنني عندما كنت أعمل، وعندما كنت مقتدرًا كنت أخصص لوالدي مبلغًا من المال، فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"واجب الوالد تجاه ولده المحتاج والعاجز عن العمل","answer":"الجواب:  الواجب على والدك، وعلى إخوتك أن يساعدوك، وأن يعطوك من أموالهم ما يعينك إذا استطاعوا ذلك، ولعل امتناعهم من مساعدتك لقصد حثك على العمل حتى لا تكسل، ولعلهم يكذبونك في دعوى العجز، فأنت اتق الله، وبادر بالعمل حتى تستغني عنهم، وعن غيرهم، اجتهد في العمل في التجارة، في الوظيفة إذا تيسرت وظيفة مباحة طيبة، في الخدمة في العمل، خطاط بناء، حداد، نجار، اجتهد في العمل الذي تستطيعه، يقول النبي ﷺ لما سئل: أي الكسب أطيب؟ قال -عليه الصلاة والسلام-: عمل الرجل بيده، وكل بيع مبرور ويقول ﷺ: ما أكل أحد طعامًا خيرًا من أن يأكل من عمل يده، وإن نبي الله داود كان يأكل من عمل يده. فاتق الله، واعمل، واجتهد في أي عمل؛ يدر عليك من الأعمال المباحة الطيبة، فإن عجزت؛ فالواجب عليهم أن ينفقوا عليك، ولا مانع أن تسأل من إخوانك الأغنياء أن يساعدوك من الزكاة وغيرها، إذا كنت صادقًا في أنك عاجز عن العمل، ولم يحصل لك وظيفة. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10126/واجب-الوالد-تجاه-ولده-المحتاج-والعاجز-عن-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42805.mp3","categories":["النفقات","بر الوالدين"]},{"id":12065,"question":"هل من بر الوالدين طاعتهم في الزواج من امرأة اختاروها لي، لا أرغب الاقتران بها؟","title":"حكم إجبار الوالدين ولدهما على الزواج بفتاة لا يرغبها","answer":"الجواب:  الزواج لابد فيه من الرغبة، الله يقول -جل وعلا-: وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُمْ مِنْ أَنفُسِكُمْ أَزْوَاجًا لِتَسْكُنُوا إِلَيْهَا وَجَعَلَ بَيْنَكُمْ مَوَدَّةً وَرَحْمَةً [الروم:21]، فإذا كانت المرأة المخطوبة لا تناسبك، ولا ترضاها، ولا ترغب فيها؛ لم يلزمك طاعة والديك في ذلك؛ لأن هذا شيء يخصك، وأنت أعلم بنفسك، ولا يجوز لهما إلزامك بامرأة تكرهها، هذا لا يجوز لهما، والله -جل وعلا- أوجب عليهما الإنصاف والعدل، فليس لهما إجبارك على ما يضرك، وأنت أيضًا لا يلزمك طاعة الوالدين في غير المعروف: إنما الطاعة في المعروف وليس من المعروف أن تطيعهما في امرأة لا ترضاها، ولا تناسبك. أما إذا كنت ترضاها وتناسبك، وأحبا أن تتزوجها؛ فهذا خير إلى خير؛ تطيعهما؛ لأنها مصلحة ظاهرة، أما امرأة لا ترضاها؛ إما لضعف دينها، وإما لعدم جمالها، وإما لأسباب أخرى تعلم من نفسك أنك لا ترغب فيها، وتخشى من أن تخسر بدون فائدة، فإنه لا يلزمك، ولا يجوز لهما إلزامك، ولكن تسترضيهما بالكلام الطيب، والأسلوب الحسن؛ حتى يخضعا لقولك، وحتى يرضيا بالمرأة المناسبة، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10250/حكم-اجبار-الوالدين-ولدهما-على-الزواج-بفتاة-لا-يرغبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43414.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":12110,"question":"يقول عن والدته سماحة الشيخ، والدتي تبلغ من العمر خمسين سنة، إلا أنها هداها الله ضعيفة في أداء الصلوات الخمس، هكذا يقول، وأردت نصحها عدة مرات، وسنين طويلة، ووالدي كذلك وهو الآن حي، والحمد لله، لكني ألاحظ أن الأمر كما هو، فبماذا توجهوننا جميعًا؟ جزاكم الله خيرًا.","title":"واجب الابن تجاه أمه المتساهلة بأداء الصلاة","answer":"الجواب:  الواجب عليها أن تتقي الله، وأن تحافظ على الصلاة في أوقاتها؛ لأن الصلاة عمود الدين، وأعظم الفرائض، وأهمها بعد الشهادتين، فالواجب على كل مسلم، وعلى كل مسلمة المحافظة على الصلوات في أوقاتها بكل عناية، لقول الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، وقوله سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونََ [النور:56] وقوله -جل وعلا-: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2]، ثم قال في آخر الآيات: وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ [المؤمنون:9]. فالمقصود: أن الواجب على المؤمن والمؤمنة العناية بالصلاة، والمحافظة عليها أينما كان في السفر والإقامة، في الشدة والرخاء، في الصحة والمرض، في الغنى والفقر، حتى ولو كان على فراشه يصلي، إن كان يستطيع يصلي قاعدًا؛ صلى قاعدًا، فإن عجز؛ صلى على جنبه، فإن عجز؛ صلى مستلقيًا، ليس له عذر في الترك أبدًا ما دام عقله معه، ويقول النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة ويقول أيضًا -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة يعني: والمرأة، المعنى واحد، يعني: الخطاب للرجل والمرأة، هذا يعم الجميع، ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. والواجب عليك أنت يا ولدها النصيحة، وهكذا زوجها يجب عليه أن ينصحها، وأن يؤدبها أيضًا، ولو بالضرب حتى تستقيم على المحافظة، وإذا تعمدت تركها؛ تكفر بذلك -نسأل الله العافية- وينبغي له فراقها حينئذٍ إذا كفرت، الواجب عليه فراقها، لا يبقى المسلم مع الكافرة غير الكتابية. المقصود: الواجب عليكما جميعًا أنت وأبوك العناية بها، أنت تنصح بالكلام الطيب، والأسلوب الحسن، وأبوك كذلك، وله سلطان عليها بأن يؤدبها إذا .... وتساهلت بالصلاة -نسأل الله لها الهداية- وأن يعيذها مولاها من الشيطان، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10295/واجب-الابن-تجاه-امه-المتساهلة-باداء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43713.mp3","categories":["حكم الصلاة وأهميتها","بر الوالدين"]},{"id":12154,"question":"أيضًا تقول عن والدها هذا: إنه لم يسمح لهن بالاحتجاب عن زوج الأخت، وعن ابن العم؛ بحجة أنهم من المحارم، وقد وضحنا له ذلك، وقلنا: ليسوا من المحارم، فغضب علينا غضبًا شديدًا، ولاسيما وأننا دائمًا نستمع إلى هذا البرنامج، وننقل إليه ما نسمع، لكنه غير مقتنع، فما هو توجيهكم لنا تجاه والدنا ذلكم؟ جزاكم الله خيرًا.","title":"هل زوج الأخت وابن العم من المحارم؟","answer":"الجواب:  زوج الأخت ليس محرمًا، إلا أن تكون هناك رضاعة بينه وبين البقية، وإلا ليس محرمًا؛ لأن زوج الأخت ليس محرمًا، لكن لو كان بينه وبين أخواتها رضاعة شرعية؛ صرن محارم له، دون زوجته. المقصود: أن زوج الأخت، وزوج العمة، وزوج الخالة ليسوا محارم، المحرم زوج الأم، زوج البنت، زوج الجدة، زوج بنت البنت، بنت الابن هذا محرم، أما زوج الأخت، وزوج الخالة، وزوج العمة، وزوج بنت العمة هذا ليس محرمًا. وهكذا ابن العم ليس محرمًا، لا، ابن العم وابن الخالة ليسا محرمًا، أما ابن الأخت هذا محرم، ابن الأخت محرم، لأن المرأة خالته، يكون محرمًا، يكون محرمًا لها، وهكذا ابن أخيها تكون عمته محرمًا لها. والواجب على أبيك أن يتقي الله، وأن يساعد على الخير، نسأل الله له الهداية، الواجب عليه أن يتقي الله، وألا يفتي بغير علم، وألا يمنعكن من الحق، فالواجب عليكن التستر والحجاب، ولا يجوز طاعته في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق. فالواجب عليكن طاعة الله ورسوله، وليس طاعة الأب، ولا غير الأب في المعصية، فعليكن الاحتجاب من زوج الأخت، ومن ابن العم، ومن ابن الخال، وابن الخالة، إلا أن يكون بينكم وبينه رضاعة، عليكن أن تحتجبن عنه مثل بقية ..... هذا هو الواجب، الله يقول -جل وعلا- في كتابه العظيم: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] الآية من سورة الأحزاب، ويقول سبحانه في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] والبعولة: الأزواج إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ [النور:31] هؤلاء المحارم، وهكذا الأخوال والخالات مما ذكرت في النور أيضًا من آخرها. المقصود: أن المحارم لا بأس بأن تكشف لهن المرأة، تكشف عن وجهها، عن يديها، عن قدميها؛ لا بأس بهذا، والحشمة للبقية أحسن وأحوط، الحشمة للرأس ونحوه، حتى لا تقع فتنة، وإلا محرمها لو رأى رأسها، أو رأى صدرها؛ ما يضر، لكن إذا كانت محتشمة، إنما تبدي وجهها وكفيها، فيكون هذا أفضل وأحوط وأحسن، وأبعد عن الشر. المقصود: أن زوج الأخت ليس محرمًا، وابن العم ليس محرمًا وابن الخالة ليس محرمًا، وابن العمة ليس محرمًا، وهكذا الجار ليس محرمًا، الجيران ليسوا محارم إلا إذا كانوا من أقارب المحارم، أخولًا أو أعمامًا أو أخوة أو أزواجًا، أو آباء، أزواجًا أو ما أشبه ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، كيف يقابلن غضب الوالد ذلكم، جزاكم الله خيرًا؟ الشيخ: الواجب على كل حال المخاطبة الطيبة، والرفق به، وأن يكلم مثلًا الطيب، يخبرنه بالفتاوى التي تنشر من طريق نور على الدرب، أو من طريق فتوى أهل العلم، حتى يتبين له الصواب، وإذا تيسر أن بعض أهل العلم ممن تعرفون تقلن له: ينصحه، ويتصل به، ولد من طريق الهاتف، أو من طريق المكاتبة؛ لا بأس، أو تنصحونه يسمع \"نور على الدرب\" يسمع الشريط الذي فيه هذه المسائل؛ لعل الله يهديه.  المقصود: أن الواجب عليكن الرفق، والكلام الطيب مع الوالد، حقه كبير، وإن أساء إليكن؛ فعليكن أنتن بالكلام الطيب، والرفق، والسيرة الحميدة مع الوالد، ومع الوالدة، أبدًا دائمًا دائمًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، لكن لا يطعنه في الكشف على غير المحارم؟ الشيخ: لا يطاع الأب، ولا الأم، ولا غيرهما في المعصية، لا في هذا، ولا في غيره: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10339/هل-زوج-الاخت-وابن-العم-من-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44104.mp3","categories":["قضايا المرأة","بر الوالدين","النظر والخلوة والاختلاط"]},{"id":12185,"question":"هل يجوز للمرأة أن توفر النقود من مصروفها ومصروف البيت والأولاد دون علم زوجها، مع العلم أن ذلك لا يؤدي إلى بخل أو تقتير، بل من باب عدم الإكثار والإسراف في المصاريف، يعني: الاقتصاد في المصروف؟","title":"حكم ادخار الزوجة من مصروف بيتها دون علم زوجها","answer":"الجواب:  إذا كان ذلك لمصلحة شرعية، وهو عدم الإسراف، وعدم التبذير؛ فهي مأجورة، لكن تخبر الزوج بذلك، تخبر الزوج بذلك حتى يصرف المال في جهة أخرى، أما أن تدخره لنفسها دون علم الزوج؛ فلا، فإذا كان الاقتصاد لمصلحة البيت، ومصلحة الزوج، وعن علم الزوج؛ فلا بأس بذلك؛ لأن الاقتصاد مطلوب، والإسراف محذور، والتبذير كذلك. فينبغي للمرأة أن تكون مقتصدة، فإذا كان الزوج يتساهل، فينبغي لها أن تكون عندها عناية بالمصارف؛ حتى لا تصرف إلا في الوجه المناسب؛ وحتى تبتعد عن التبذير والإسراف، وإذا كان الزوج يتساهل؛ فلا ينبغي لها أن تتساهل، والمال سوف ينفعهما جميعًا، نعم. المقدم: أما دون علم الزوج كما تقول؟ الشيخ: ......... لا، لابد أن تخبره بذلك حتى يكون على بينة، وليس لها أن تأخذه لنفسها المال، بل يكون للزوج، ولمصلحة الزوج والأولاد وأهل البيت؛ حتى يكون على بينة هو؛ لأنه إذا لم تخبره قد يزين لها الشيطان أن تصرفه في حاجات أخرى لها، تخص بها نفسها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10371/حكم-ادخار-الزوجة-من-مصروف-بيتها-دون-علم-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44312.mp3","categories":["النفقات","بر الوالدين"]},{"id":12510,"question":"بعد هذا رسالة وصلت إلى البرنامج من الرياض باعثها مستمع رمز إلى اسمه بالحروف (م) و (ط) يقول: صدرت من زوجتي بعض التصرفات التي أساءت إلى والدتي التي كانت في زيارة لي بالمملكة، رغم أن والدتي تتمتع بأخلاق عالية، وهي دائمة العطف والحنان على الجميع، وتخص زوجتي بقدر كبير من ذلك منذ زواجي بها قبل أربع سنوات مضت، حتى إن أخواتي البنات يحسدونها على ذلك، إلا أن زوجتي قابلت الإحسان بالإساءة، ولم تراع كبر سن والدتي، أو كونها في زيارة لنا قد لا تتكرر، أرجو توجيهي ماذا أفعل، هل أطلق زوجتي؟ جزاكم الله خيرًا.","title":"كيفية معالجة أخطاء الزوجة تجاه أم زوجها","answer":"الجواب:  نوصيك بعلاج الموضوع بالكلام الطيب، والأسلوب الحسن، ولا تعجل في الطلاق، ولكن توصيها بالكلام الطيب، والأخلاق الفاضلة، والمعاملة الطيبة مع والدتك، ومع غيرها من أقاربك، ومن زوارك، عليها أن تتقي الله، وعليها أن تراقب الله حتى تكون زوجة صالحة ذات أخلاق كريمة مع الوالدة ومع غيرها، ولا تعجل في الطلاق إذا كانت دينة، إذا كانت من أهل الخير والصلاح لا تعجل، أما إذا كان عندها أخلاق أخرى سيئة من المعاصي فطلاقها أصلح، إذا لم ينفع فيها الوعظ والتذكير، أما هذه الزلة مع الوالدة فعالجها بالكلام الطيب, والأسلوب الحسن، والتوجيه إلى الخير، وإذا دعت الحاجة إلى تأديبها تأديبًا خفيفًا؛ فلا بأس، أو بالهجر؛ كذلك لا بأس، لكن مهما أمكن العلاج بغير الهجر والتأديب؛ فهو أولى، فعليك أن تجتهد في ذلك، وأن تسأل الله لها الهداية والتوفيق وصلاح الحال، هذا هو الأولى بك، نعم. المقدم: بارك الله فيكم، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/10708/كيفية-معالجة-اخطاء-الزوجة-تجاه-ام-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40703.mp3","categories":["النفقات","بر الوالدين"]},{"id":12856,"question":"المستمع عبدالله عبيد الفنجري بعث بسؤال ملخصه كالتالي، يقول: تزوجت بدون رضا والدتي، وأشعر بعد هذه الحالة أنني غير موفق، فهل ذلكم هو السبب؟","title":"حكم من تزوج دون رضا والدته","answer":"الجواب:  لا شك أن مشاورة الوالدة من أهم المهمات، وحقها عظيم، ومشاورتها مهمة، وهكذا الوالد، ولكن إذا وقع الواقع فنرجو لك التوفيق، وعليك أن تستسمحها، وتطلب منها الإباحة والدعاء لك بالتوفيق، وهي -إن شاء الله- من كل خير قريب، الوالدة تحب لولدها كل خير. فعليك أن تستسمحها، وتقبل رأسها، وتطلب منها العفو والمسامحة، والدعاء لك بالتوفيق، وهي -إن شاء الله- تسمح، وفي المستقبل لا تتزوج إلا بمشاورة الوالدة والوالد ورضاهما، هذا هو الذي ينبغي لك؛ لأن حقهما عظيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11071/حكم-من-تزوج-دون-رضا-والدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46504.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":13313,"question":"السائل رأفت علي يقول في هذا  إنني قد تقدمت لخطبة ابنة عمي، وجاءت الموافقة -والحمد لله- والآن قد مضى على الخطوبة ما يقرب من سنة، ولكن والدتي غير راضية عن هذه الخطوبة من ابنة عمي، وأنا أعرف بأن هذه البنت تصلي، وتقوم بالأمور الشرعية، وملتزمة بالحجاب الشرعي، وتقوم بالليل، وأنا الآن في حيرة من إحراج عمي، وفي حيرة أخرى من ناحية والدي، ومحتار، فما هو الحل في نظركم سماحة الشيخ؟","title":"مراعاة رأي الأم في اختيار الزوجة","answer":"الجواب: الواجب على والدتك أن تتقي الله، وأن لا تمنعك من هذا الزواج الذي ينفعك ولا يضرك ما دامت البنت على ما ذكرت، فالواجب على الوالدة الموافقة، لكن إذا وجدت ابنة تناسب الوالدة، وهي أيضًا تناسبك من جهة دينها، وخلقها وخلقها؛ فلا بأس إذا جمعت بين المصلحتين، إذا تيسر بنت ترضاها، وترضاها الوالدة؛ فهذا خير؛ لأن بر الوالدة مهم، ومراعاة خاطرها مهم، فإذا تيسرت لك زوجة غير هذه ترضاها الوالدة؛ فاحرص على ذلك. أما إذا لم يتيسر ذلك؛ فليس لها أن تمنعك، ولك أن تتزوج وإن لم ترض؛ لأن الرسول ﷺ قال: إنما الطاعة في المعروف وزواجك معروف فيه خير كثير، ومصالح جمة إذا كانت الزوجة صالحة، والحمد لله، وعليك أن ترضي الوالدة بالكلام الطيب، والأسلوب الحسن حسب الطاقة، لكن إن تيسرت امرأة ترضاها أنت، وترضاها الوالدة فهذا أكمل، وأطيب.","link":"https://binbaz.org.sa/fatwas/11599/مراعاة-راي-الام-في-اختيار-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52105.mp3","categories":["الخِطْبَة والاختيار ","بر الوالدين"]},{"id":13589,"question":"السائل في ثاني أسئلته يقول: سماحة الشيخ! إذا حدث سوء تفاهم، أو شجار بين الزوج وزوجته تقوم الزوجة بالذهاب إلى أهلها فترة من الزمن، وعندما يريد الزوج أن يعيدها إلى بيته، وحل الخلافات بينهما؛ يفاجأ بأهل الزوجة بطلب مبالغ كبيرة من المال، وذلك حق الجلوس عند أهلها، هل يجوز إعطاء أهل الزوجة مثل هذه المبالغ، وذلك مقابل قعود هذه المرأة عند أهلها؟","title":"حكم دفع المال مقابل جلوس الزوجة عند أهلها","answer":"الجواب:  نعم، أحسن حتى تتم العشرة، وتبقى المودة، وإن تيسر استسماحهم، أو التوسيط إلى من يستسمحهم في الكل، أو البعض؛ فلا بأس، وإذا تيسر أن ترضيها بما قال أهلها، وتعطيهم ما طلبوا؛ لعل ذلك يكون فيه خير كثير لكما جميعًا؛ لأجل تهدأ الأوضاع، وتستقيم الأحوال، وتستمتع بزوجتك بحالة طيبة. على كل حال هذا يرجع إليك إن سمحت، فهذا خير عظيم، ولا سيما مع القدرة، وإن شق عليك ذلك توسط لها الأخيار، والطيبين حتى يصلحوا بينك وبينهم بوضع التكاليف هذه، أو بعضها. نعم. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11949/حكم-دفع-المال-مقابل-جلوس-الزوجة-عند-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53319.mp3","categories":["النفقات","بر الوالدين"]},{"id":13642,"question":"في أسئلة هذا السائل من جمهورية مصر العربية يقول: متى تبدأ النفقة على الزوجة، هل هو من العقد، أم من الدخول عليها؟","title":"متى تبدأ النفقة على الزوجة؟","answer":"الجواب: يبدأ من الدخول عليها، إذا دخل عليها، وصارت تحت تصرفه، وتحت نفقته تبدأ النفقة عليها، أما مادامت عند أهلها؛ فلا نفقة لها إلا إذا كان التأخير منه هو الذي أخرها، أما إذا كان الامتناع منهم، طلبوا منه تأجيلها؛ فإن النفقة عليهم. أما إذا هو الذي تركها عندهم متساهلًا؛ فالظاهر أن عليه النفقة؛ لأن هذا التساهل يشبه أن يكون فرارًا من النفقة، وقد دخلت في عصمته، والله -جل وعلا- أمر بالمعاشرة بالمعروف، قال: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] وليس من المعروف أن لا ينفق عليها، وقال النبي ﷺ: ولهن عليكم رزقهن وكسوتهن بالمعروف وهذا يعم المدخول بها، وغير المدخول بها، إلا إذا كان بقاؤها عند أهلها باختيارهم، ورغبتهم هم فالنفقة عليهم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11975/متى-تبدا-النفقة-على-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52815.mp3","categories":["النفقات","بر الوالدين"]},{"id":13801,"question":"أختنا تقول: تركت الدراسة ووالدتي غير راضية هل أكون آثمة؟","title":"حكم ترك الدراسة بغير رضا الوالدين","answer":"الجواب: الدراسة فيها خير عظيم وفائدة كبيرة، والواجب على المسلم والمسلمة التعلم والتفقه في الدين؛ لأنه يجب على المسلم أن يتفقه في دينه وأن يتعلم ما لا يسعه جهله، ومن أسباب السعادة التفقه في الدين، كما قال النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين متفق على صحته. فمن علامات الخير والسعادة التفقه في دين الله، التفقه في الإسلام في أحكام الشريعة حتى يعرف المؤمن والمؤمنة ما يجب عليه ما يحرم عليه، وحتى يعبد الله على بصيرة، ويقول النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة.\nفالواجب عليك التعلم والتفقه في الدين إذا تيسر ذلك في مدارس إسلامية طيبة أمينة، وإذا أكدت عليك أمك كان هذا مما يوجب مزيد العناية والحرص على التفقه في الدين؛ لأنها تريد لك الخير والمصلحة العاجلة والآجلة، فلا ينبغي منك أن تعصيها في ذلك إلا إذا كانت المدرسة فيها اختلاط أو فيها أمور أخرى تضرك في دينك فلا حرج عليك إذا تركت الدراسة ولو لم ترض أمك؛ لأن الرسول عليه السلام يقول: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق، نسأل الله أن يمنحك التوفيق. نعم.\nالمقدم: أثابكم الله وسدد خطاكم، وكتب لكم الأجر والثواب.","link":"https://binbaz.org.sa/fatwas/12209/حكم-ترك-الدراسة-بغير-رضا-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60210.mp3","categories":["بر الوالدين","العالم والمتعلم"]},{"id":13807,"question":"أختنا تقول: تركت الدراسة ووالدتي غير راضية هل أكون آثمة؟","title":"حكم ترك الدراسة بغير رضا الوالدين","answer":"الجواب: الدراسة فيها خير عظيم وفائدة كبيرة، والواجب على المسلم والمسلمة التعلم والتفقه في الدين؛ لأنه يجب على المسلم أن يتفقه في دينه وأن يتعلم ما لا يسعه جهله، ومن أسباب السعادة التفقه في الدين، كما قال النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين متفق على صحته. فمن علامات الخير والسعادة التفقه في دين الله، التفقه في الإسلام في أحكام الشريعة حتى يعرف المؤمن والمؤمنة ما يجب عليه ما يحرم عليه، وحتى يعبد الله على بصيرة، ويقول النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة.\nفالواجب عليك التعلم والتفقه في الدين إذا تيسر ذلك في مدارس إسلامية طيبة أمينة، وإذا أكدت عليك أمك كان هذا مما يوجب مزيد العناية والحرص على التفقه في الدين؛ لأنها تريد لك الخير والمصلحة العاجلة والآجلة، فلا ينبغي منك أن تعصيها في ذلك إلا إذا كانت المدرسة فيها اختلاط أو فيها أمور أخرى تضرك في دينك فلا حرج عليك إذا تركت الدراسة ولو لم ترض أمك؛ لأن الرسول عليه السلام يقول: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق، نسأل الله أن يمنحك التوفيق. نعم.\nالمقدم: أثابكم الله وسدد خطاكم، وكتب لكم الأجر والثواب.","link":"https://binbaz.org.sa/fatwas/12209/حكم-ترك-الدراسة-بغير-رضا-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60210.mp3","categories":["بر الوالدين","العالم والمتعلم"]},{"id":14190,"question":"السائل إبراهيم عبد العزيز له هذا السؤال، يقول: سماحة الشيخ! يوجد لي ولله الحمد ثلاثة بنات وولد، وأكبرهم بنت عمرها الآن ستة عشر عامًا، وولدت هذه البنت معوقة في ساقها، وقام الطبيب بإجراء عملية في بتر ساقها وتركيب جهاز لتمشي عليه، والحمد لله هي الآن تمشي عادي، ولكن هل علينا إثم في هذه العملية، وثانيًا هذه البنت تقوم بتغيير هذا الجهاز في كل ثلاث سنوات أو أربع ويتكلف مبلغًا من المال، هل إذا قمت بترك مبلغ من المال باسم البنت لتتمكن من تبديل الجهاز وقت ما تحتاج لذلك هل أكون قد ظلمت باقي الأخوات؟","title":"حكم الزيادة في النفقة لبعض الأبناء للحاجة","answer":"الجواب: إذا كانت فقيرة، لا، هذا واجب أنت تنفق عليها مثل نفقتها، هذا من باب النفقة ليس من باب العطية، فأنت مأجور ولا حرج، إذا كانت فقيرة محتاجة إلى ذلك ليس عندها مال. نعم. الله المستعان.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12643/حكم-الزيادة-في-النفقة-لبعض-الابناء-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54722.mp3","categories":["النفقات","بر الوالدين"]},{"id":14196,"question":"هذه الزوجة التي رمزت لاسمها بـ (هـ. م. م) تقول: بأنها امرأة مصرية مقيمة بمكة المكرمة وتؤرقها هذه المشكلة، تقول: تزوجت من شاب ملتزم دون رضا والدته بعد أن كانت وافقت على الخطبة، بل قامت بالحضور إليها وباركتها لكنها غيرت رأيها؛ لأن هناك من وشى لها ولهذا رفضت إتمام الزواج وأرادت أن تفسخ هذه الخطبة، لكننا تزوجنا أنا وزوجي..الشيخ:أعد.. أعد..المقدم: تقول: تزوجت من شاب ملتزم دون رضا والدته بعد أن كانت قد وافقت على الخطبة بل وحضرتها وباركتها، لكنها غيرت رأيها في الأخير؛ لأن هناك من وشى لها ولهذا فقد رفضت إتمام الزواج وأرادت أن تفسخ هذه الخطبة لكننا تزوجنا على أمل أنها قد تغير رأيها بمرور الأيام، ولكن مضى أربع سنوات وزوجي يسعى لإصلاحها ولكنها ترفض وطلبها الوحيد هو أن يطلقني، وأنا الآن معي ما يقارب من طفلين ونعيش مع زوجي حياة طيبة، ما حكم هذا الأمر وهل زوجي يعتبر عاق؟","title":"حكم زواج الابن بغير رضا والدته","answer":"الجواب: إذا كان الزواج شرعيًا فلا بأس عليه وليس بعاق، والواجب عليها أن تعينه على الزواج وأن لا تمنعه من الزواج إذا كانت الزوجة لا بأس بها في دينها فليس لها حق -الوالدة- أن تمنعه.\nالمقصود أنه إذا كان الزواج شرعيًا لا محذور فيه فإنه قد أحسن لما في ذلك من إعفاف نفسه، والمسارعة إلى ما شرع الله، والواجب عليها هي التوبة إلى الله وأن لا تمنعه من الزواج وأن لا تأمره بطلاق امرأته إلا من علة.\nأما إذا كانت الزوجة غير مرضية في دينها هذا له وجه، إذا كانت السائلة غير مرضية وهي الزوجة وأمه ترغب به عنها لأنها غير مرضية في دينها لفسقها ومعاصيها أو تهمتها بالفساد فهذا له وجه، ينبغي له طاعة أمه في ذلك وفراق الزوجة التي لا خير فيها من جهة أعمالها الرديئة.\nفالحاصل أن التزوج أمر مطلوب، والولد عليه أن يتزوج ولو أبى والداه، عليه أن يتزوج ويعف نفسه، وعليهما أن يساعداه، على والديه أن يساعداه، لكن إذا كانت المخطوبة غير صالحة في دينها فالواجب عليه أن يلتمس غيرها ولا يعصي والديه. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12649/حكم-زواج-الابن-بغير-رضا-والدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54803.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":14734,"question":"يقول: اشتريت مزرعة من مالي الخاص، والذي أشقى به في الخارج، وكتبت المزرعة بعقد رسمي باسمي، فهل والدي وإخوتي البنين والبنات لهم حق في هذه المزرعة أم لا؟أفيدوني، أفادكم الله.","title":"هل يحق للوالد أن يأخذ من مال ولده؟","answer":"الجواب: نعم، والدك له حق، له حق أن يأكل منها: أنت ومالك لأبيك يقول النبي ﷺ: أنت ومالك لأبيك ويقول ﷺ: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم فللوالد أن يأكل منها، ويستفيد منها، وله أن يأخذ منها ما لا يضرك، يأخذ منها ما لا يضرك: فاكهة، تمر، حبوب شيء لا يضرك.  أما الذي يضرك ويضر عائلتك لا، لا يأخذ شيئًا يضرك.\nوأما إخوانك وأعمامك لا ليس لهم إلا بإذنك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13228/هل-يحق-للوالد-ان-ياخذ-من-مال-ولده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49007.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":14737,"question":"ما هي نفقة المتعة؟ وهل تحق لزوجتي؟ وكيف تقدر؟","title":"ما حكم نفقة متعة المطلقة؟ وكم مقدارها؟","answer":"الجواب: يستحب لك تمتيعها؛ لقول الله تعالى: وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ [البقرة:241] يستحب لك تمتيعها بما تيسر من المال: كسوة أو نقود، وليس لها حد محدود بما يسر الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13235/ما-حكم-نفقة-متعة-المطلقة-وكم-مقدارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63003.mp3","categories":["النفقات","بر الوالدين"]},{"id":15270,"question":"هل من كلمة -يا سماحة الشيخ- لهؤلاء الأزواج الذين تلزمهم النفقة على زوجاتهم وأولادهم؟","title":"نصيحة لمن يهملون النفقة على زوجاتهم وأبنائهم","answer":"الجواب: نعم، الواجب على كل زوج أن ينفق على زوجته، وعلى أولاده، وأن يتقي الله في ذلك، إلا إذا كان عندها مال، وسمحت فلا بأس، وإلا فالواجب عليه أن يتقي الله، وأن يراقب الله، وأن ينفق عليها، وعلى أولادها نفقة مثلها، هذا هو الواجب، قال النبي ﷺ في الأزواج: وعليهم رزقهن وكسوتهن بالمعروف على الزوج كسوة الزوجة بالمعروف، يكسو أولاده، وقال تعالى: وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ [البقرة:233]. فالواجب على الزوج أن يتقي الله، وأن ينفق على الزوجة، وعلى الأولاد النفقة التي تنفق على أمثالهم، يعني: النفقة التي تناسب مثلهم، لا إسراف، ولا تقتير، إلا إذا كانت امرأة غنية وسامحته، وأنفقت على نفسها فلا حرج.","link":"https://binbaz.org.sa/fatwas/13770/نصيحة-لمن-يهملون-النفقة-على-زوجاتهم-وابناىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56515.mp3","categories":["النفقات","بر الوالدين"]},{"id":15759,"question":"رسالة وصلت إلى البرنامج من جمهورية مصر العربية محافظة المنيا، وباعث الرسالة المستمع خالد طلعت عبدالله علي، الأخ خالد يقول في رسالته: لرجل ابنان متزوجان، وكلاهما يعول أسرة، أحد هذين الابنين حالته ميسرة، والآخر نفقاته كثيرة، ويحتاج إلى بعض العون، فقام الأب بتخصيص دخل ثابت لابنه المحتاج هذا برغبة الوالد، ودون طلب من ابنه هذا، إلا أن الابن الآخر ثار على والده وأخيه، واعتبر أن أباه يفضل أخاه عليه. و هل هذا جائز شرعًا؟ علمًا بأن الابن ينتفع بهبة والده له في حياته فقط.جزاكم الله خيرًا.","title":"حكم إنفاق الأب على الابن الفقير دون الغني","answer":"الجواب: إذا كان أحد الابنين فقيرًا، وليس عنده أسباب تقوم بحاله، فعلى الوالد أن ينفق عليه إذا كان قادرًا، والابن الغني لا حق له في ذلك، فإذا كان عنده أولاد بعضهم فقراء، وبعضهم أغنياء، والوالد يقدر على النفقة، وجب عليه الإنفاق على الفقراء، وإن كانوا كبارًا، إذا لم يكن عندهم أسباب تغنيهم، ولا كسب يغنيهم؛ لأن النفقة أمر لازم على الوالد أن ينفق على ولده الفقير. أما إذا كانوا كلهم أغنياء، فليس له أن يخص أحدًا بالعطية؛ لقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم فالواجب أن يعدل إن كانوا فقراء، أنفق عليهم، وأعدل فيهم، وإن كانوا أغنياء أعدل فيهم أيضًا، أعطاهم جميعًا، أو تركهم جميعًا، أما إذا كان أحدهم فقيرًا، والبقية أغنياء، أو أكثرهم فقراء، وبعضهم أغنياء، فإنه ينفق على الفقير، وليس هذا بظلم، بل واجب عليه أن ينفق إذا كان الفقير ما عنده أسباب، ما عنده كسب، لا يستطيع الكسب، فإن الوالد إذا كان قادرًا عليه ينفق عليه ويواسيه بنفقة أمثاله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14346/حكم-انفاق-الاب-على-الابن-الفقير-دون-الغني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74106.mp3","categories":["الهبة والعطية","النفقات","بر الوالدين"]},{"id":15776,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع (ب. م. ح) من جمهورية مصر العربية، أخونا سأل في حلقة مضت بعض الأسئلة، وفي هذه الحلقة يسأل ويقول: إنني منفصل عن والدي، ولي بيت مستقل، وأبي له حانوت يحتوي على بعض البضائع، وتعطيني والدتي من ذلك الحانوت دون علم والدي، فهل ما آخذه يعتبر حلالًا أم لا يجوز؟جزاكم الله خيرًا.","title":"حكم إعطاء الأم ابنها من مال أبيه دون علمه","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفإن كنت فقيرًا لا تستطيع الكسب، وليس عندك ما يقوم بحالك فلا حرج، إذا كان ما تعطيك والدتك من الحانوت لا يضر والدك فلا بأس؛ لأن عليه أن ينفق عليك، كما تأخذ الزوجة من مال زوجها حاجتها، وإن لم يرض، وإن لم يعلم؛ لأن عليه أن ينفق عليها، أما إن كنت في غنى وفي سعة فليس لك أن تقبل ذلك إلا بإذن والدك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14364/حكم-اعطاء-الام-ابنها-من-مال-ابيه-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74201.mp3","categories":["النفقات","بر الوالدين"]},{"id":16034,"question":"تقول: أنا فتاة أعيش مع أمي وأبي وأخي، مع العلم أن جميع إخوتي وأخواتي قد تزوجوا، وأقوم أنا بالإنفاق على أهلي، فهل تلزمني النفقة عليهم؟ وإذا امتنعت عن ذلك أكون آثمة، والعياذ بالله؟","title":"حكم إنفاق الأبناء على الآباء والإخوة","answer":"الجواب: إذا كنت قادرة، عندك مال، سواء من طريق الوظيفة، أو غيرها، وأبوك عاجز، وأمك عاجزة، وأخوك عاجز؛ وجب عليك الإنفاق، وهذا من صلة الرحم، ومن بر الوالدين، بشرطين: أحدهما: أن تكوني قادرة عندك مال. والشرط الثاني: أن يكونوا فقراء عاجزين. أما إذا كنت عاجزة؛ فلا يكلف الله نفسًا إلا وسعها، أو كانوا أغنياء؛ فإنه لا يلزمك النفقة عليهم، وأبشري بالخير في الإنفاق عليهم إذا أحسنت وصبرت، ولو كانوا أغنياء فهذا بر عظيم، وخير كبير، ولكن لا يلزمك إلا بالشرطين: قدرتك وعجزهم، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14666/حكم-انفاق-الابناء-على-الاباء-والاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74804.mp3","categories":["النفقات","بر الوالدين"]},{"id":16100,"question":"السائلة تقول: هل من الواجب على الزوج النفقة على زوجته في الفترة التي تقضيها في منزل والدها عندما يقوم بتأثيث منزلهم الجديد -أي: في فترة الملكة قبل الزواج- لأن والدي يقول: يجب على زوجك النفقة عليك من يوم الملكة، وإن هذا واجب عليه؟","title":"حكم النفقة على المعقود عليها قبل الدخول بها","answer":"الجواب: هذا فيه تفصيل: إن كان هو تزوجها، وقال: خلوها عندكم عليه النفقة، أما إذا كان أهلها، أو هي طلبت البقاء عند أهلها لحاجاتهم؛ فلا نفقة عليه حتى تصل إليه، أما إذا أبقاها عندهم لمصلحة رآها هو؛ هذا ينفق عليها، نعم.","link":"https://binbaz.org.sa/fatwas/14743/حكم-النفقة-على-المعقود-عليها-قبل-الدخول-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57920.mp3","categories":["النفقات","بر الوالدين"]},{"id":16211,"question":"رسالة بتوقيع أحد الإخوة المستمعين يقول: ابنكم (د. هـ. ف) له قضية يقول فيها: أنا شاب ولي أمر عائلتي، وتقدم لأختي شاب خاطبًا لها، وبعد التأكد من استقامته؛ قبلت به بعد موافقة والدتي أيضًا، وتمت بعد ذلك الرؤيا بين أختي وذلكم الشاب -وبحمد الله- كل منهما موافق، ولكن بعد أيام فوجئت بتحول رأي الوالدة عن هذا الزواج؛ بحجة صغر سن هذه الأخت.يا سماحة الشيخ! إنه سبق وأن تقدم ثلاثة خطاب قبل هذا الشاب، وترفض الوالدة بحجة صغر سن البنت، علمًا بأن عمرها يقارب الرابعة والعشرين، وجهوني كيف أوفق بين وجوب تزويج هذه البنت، وبين رضا والدتي وتصرفاتها هذه، جزاكم الله خيرًا.","title":"التوفيق بين الزواج وطاعة الوالدة","answer":"الجواب: بنت أربعة وعشرين ليست صغيرة، بل كبيرة، قد تجاوزت وقت الزواج؛ فلا يجوز لوالدتك أن تمنع، ولا أن تحتج بهذه الحجة، وإذا كانت البنت راضية؛ فزوِّجها، ولو لم ترض أمك، يجب عليك أن تزوجها؛ لأن في ذلك عفتها، والسعي في سلامة عرضها، والجمع بينها وبين الخاطب المناسب، والحمد لله، والرسول يقول ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق والتأخر عن تزويجها مع وجود الكفء، ومع رغبتها؛ معصية. فالواجب عليك تنفيذ الزواج، والمشورة على والدتك بالكلام الطيب، أن تسمح، وأن ترضى؛ حتى يكون الأمر -إن شاء الله- عن رضا الجميع، فإن أبت، وأصرت؛ فطاعة الله مقدمة، إذا كانت البنت راضية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14878/التوفيق-بين-الزواج-وطاعة-الوالدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75106.mp3","categories":["حكم الزواج وأهميته","بر الوالدين"]},{"id":16418,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من اليمن الحديدة بتوقيع إحدى المستمعات تقول فاطمة (هـ. ع) فاطمة تقول عن نفسها: أنا فتاة في التاسعة عشرة من عمري، وملتزمة بالحجاب الشرعي، ولله الحمد، ولكني أجد بعض المضايقات من قبل والدي، مثل إصرارهما على ظهوري على الرجال الأقارب من غير المحارم، ومصافحتهم، مثل ابن العم، وابن الخال، وزوج الخالة، وابن عم الأم، فما حكم ذلك، وهل يعتبر رفضي لذلك عقوقًا للوالدين؟ جزاكم الله خيرًا.","title":"حكم طاعة الوالدين في الاختلاط ومصافحة الأجانب","answer":"الجواب: أنت مشكورة على عنايتك بالدين، وعلى حجابك الشرعي، وعلى سؤالك عما يهمك في دينك، أنت مشكورة على هذا، وهذا هو الواجب، الواجب على كل مسلم ومسلمة التفقه في الدين، والسؤال عما أشكل عليه، سؤال أهل العلم، يقول الله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] ويروى عنه -عليه الصلاة والسلام-: أن جماعة أفتوا بغير علم فقال: ألا سألوا إذا لم يعلموا، إنما شفاء العي السؤال ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله له به طريقًا إلى الجنة وإرسال الأسئلة إلى هذا البرنامج من سلوك الطريق، والذهاب إلى حلقات العلم من سلوك الطريق، والتعلم في المدارس من سلوك الطريق. ويقول النبي ﷺ في الحديث الصحيح أيضًا: من يرد الله به خيرًا؛ يفقهه في الدين فهذا يدل على أن التفقه في الدين من علامات الخير، وأن الإعراض من علامات الشر. وليس لك أيها الأخت في الله! ليس لك طاعة والديك في الكشف على الأقارب غير المحارم، كابن العم، وابن الخال، ونحو ذلك، وليس لك المصافحة لهم أيضًا، وليست معصية والديك في هذا من العقوق، النبي  يقول: إنما الطاعة في المعروف، وهذا ما هو من المعروف. ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق كونك تصافحين ابن عمك، أو ابن خالك، أو غيرهما من غير المحارم الذكور، هذا لا يجوز، المصافحة خطيرة، يقول النبي ﷺ: إني لا أصافح النساء وتقول عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام\" والمصافحة خطيرة. فالواجب عليك الحذر، والاعتذار إلى والديك بالكلام الطيب، اعتذري لهما بالكلام الطيب، وقولي: إني سألت بعض أهل العلم، فأخبروني أنه لا يجوز، وأرشديهم إلى هذا البرنامج يسمعونه، هذا برنامج مفيد، نوصي كل إنسان أن يسمع هذا البرنامج في كل مكان، فأنا أوصي، نوصي من يستمع من يريد الخير، ومن يطلب العلم، نوصيه أن يستمع لهذا البرنامج، فإنه يقوم عليه جماعة من أهل العلم، فنوصي كل من يريد الفائدة، والعلم أن يستمع لهذا البرنامج، نعم.","link":"https://binbaz.org.sa/fatwas/15126/حكم-طاعة-الوالدين-في-الاختلاط-ومصافحة-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81202.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":16656,"question":"من أسئلتها أيضًا يا سماحة الشيخ تقول: شخص أخذ من مال أبيه دون علمه لضرورة دعته إلى ذلك العمل، ثم رد هذا المبلغ بعد فترة من الزمن، من غير علمه أيضًا، ما حكم ما فعله؟ مأجورين.","title":"حكم أخْذ الابن من مال أبيه دون علمه ثم إرجاعه","answer":"الجواب:  الواجب ألا يأخذ من ماله إلا بإذنه، إلا إذا كان قصر في النفقة، إذا كان أبوه هو الذي ينفق عليه، وهو عاجز، ما عنده شيء، وأبوه هو الذي ينفق عليه، له أن يأخذ من ماله ما يحتاجه في النفقة من غير إسراف، من طعام، أو نقود للكسوة، من غير إسراف، إذا كان والده بخيلًا، يقصر؛ فله أن يأخذ ما يكمل النفقة، أما أن يأخذ أموالًا زيادة على هذا لتجارته، أو لأسباب أخرى لا، ليس له أن يأخذ، لا يأخذ إلا بإذن؛ لأن أموال الغير محرمة على نفسه، يقول النبي ﷺ: كل المسلم على المسلم حرام: دمه، وماله، وعرضه. ليس للإنسان أن يأخذ من مال أخيه إلا بحق، ولو زعم أنه سيرده، ولو أنه على سبيل القرض، إلا بإذنه، لكن إذا كان ذلك يتعلق بطعامه، وشرابه، وكسوته؛ لأن أباه كان يقصر في سد حاجته، فله أن يأخذ بقدر حاجته، في ملبسه، ومأكله، ومشربه. والزوجة لها أن تأخذ إذا قصر عليها، لها أن تأخذ قدر حاجتها من دون زيادة، والدليل على هذا ما ثبت في الصحيحين، عن هند بنت عتبة بن ربيعة زوجة أبي سفيان بن حرب أنها قالت: \"يا رسول الله! إن أبا سفيان رجل شحيح، لا يعطيني من النفقة ما يكفيني، ويكفي بني، فهل علي من جناح إن أخذت من ماله بغير علمه؟ فقال النبي ﷺ: خذي من ماله بالمعروف ما يكفيك، ويكفي بنيك يعني: ولو بغير علمه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15389/حكم-اخذ-الابن-من-مال-ابيه-دون-علمه-ثم-ارجاعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58313.mp3","categories":["النفقات","بر الوالدين"]},{"id":17232,"question":"تقول: يا سماحة الشيخ -هذه الأخت الطبيبة- أبي عليه ديونٌ، رغم أنه يشتغل، إلا أنه لا يستطيع تسديد هذه الديون، ولقد طلب منا نحن الأخوات البنات على مساعدته، واتفقن مع أخواتي على مبلغٍ محدد يدفع من الكل، زوجي يرفض أن أساعد أهلي، بالرغم من، أولًا: أصرف على نفسي، وعلى ابنتي، وعلى البيت من كل النواحي: إيجار، وكهرباء، ومأكل، وملبس، وغير ذلك، بل العكس أنا أساعده بالرغم من أن راتبه كبير، زوجي يصرف جميع ما يملك من الراتب على أهله، لبناء بيتٍ لأبيه، وأنا لم أعترض، بل العكس أساعده، المبلغ الذي أساعد به أهلي يعتبر جزءًا بسيطًا بالنسبة للراتب الذي أتقاضاه، أهلي موجودون في المنطقة التي أدرس بها، وهم الذين ساعدوني في أمور الحياة، مثلًا: لو احتجت الذهاب إلى مكان ما، أو طبيب، وغير ذلك، لعل لكم توجيه؟","title":"ما حكم إعانة المرأة لوالدها وزوجها رافض؟","answer":"الجواب: نعم، الواجب مساعدة والدك، عليكم أن تساعدوا الوالد، النبي ﷺ يقول: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم فعليكم أن تساعدوا والدكم، ولو لم يرض الزوج، ما له حق يمنعكم، ولو منعكم ما له حق، عليكم أن تساعدوا الوالد، ولو لم يرض الزوج، هذا من أهم الصلة، ومن أهم البر، فعليكن أن تساعدن والدكن في قضاء دينه، وفي نفقة بيته، ولو لم يرض الزوج. نعم.","link":"https://binbaz.org.sa/fatwas/16060/ما-حكم-اعانة-المراة-لوالدها-وزوجها-رافض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59109.mp3","categories":["الحقوق الزوجية","الطلاق","المشكلات الزوجية","بر الوالدين"]},{"id":17297,"question":"شخص حلف على المصحف الشريف بأنه لم يفعل شيئًا، وهو يكذب، وقد توفي هذا الشخص الآن، وأنا ابنته، تقول السائلة: أريد أن أبري ذمة والدي، فهل أعلم الشخص الذي حلف له؟ أم ماذا أفعل يا سماحة الشيخ؟الشيخ: أعد.المقدم: تقول السائلة: شخص حلف على المصحف الشريف بأنه لم يفعل شيئًا وهو يكذب، وقد توفي الآن هذا الشخص وأنا ابنته، وأريد أن أبري ذمة والدي، فهل أعلم الشخص الآخر الذي حلف له والدي؟ أم ماذا أفعل؟","title":"حكم تبرئة ذمة الوالد من حقوق المخلوقين","answer":"الجواب: إذا كنت تعرفين أن والدك أخطأ وكذب؛ فأدي عنه إذا قال: والله ما أخذت من مالك شيئًا، أو والله ما عندي لك دين، وهو يكذب؛ أعطيه حقه من مالك، وإلا من التركة، إذا كنت تعرفين هذا، إذا صدقك الورثة، وإن كان ما صدقوك أعطيه من مالك، وأبشري بالخير، والأجر، إذا كنت تعلمين أن الوالد كاذب، وأن الحق ثابت في ذمته؛ سواء دين، أو سرقة، أو غصب، أو غير ذلك، أدي أبرئي ذمة والدك، وأبشري بالخير. المقدم: ماذا يلزم هذه البنت تجاه والدها من الدعاء، والعمل الصالح؟ الشيخ: تدعو له، وتستغفر له، عليك أن تدعي له بالمغفرة، والرحمة، هذا من حقه عليك إذا كان مسلمًا. نعم. المقدم: الحمد لله، جزاكم الله خيرًا يا شيخ.","link":"https://binbaz.org.sa/fatwas/16138/حكم-تبرىة-ذمة-الوالد-من-حقوق-المخلوقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59310.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":17370,"question":"في آخر أسئلة هذا السائل يقول: سماحة الشيخ هل يحق لي أن آخذ رأي والدي في البحث عن زوجة، وبدون أن أراها، أو أعرفها؟","title":"أفضلية مشاورة الأب في اختيار الزوجة","answer":"الجواب: الأفضل أن تشاور أباك، هذا من الأدب، ومن البر أن تشاوره فيمن تخطب، تقول: يا والدي! ممكن أريد فلانة، تشاور فيه، وتشاور من يعلمها من أهل الخير، ولا تعجل حتى تطمئن إلى أنها طيبة صالحة لقوله ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك تسأل عن دينها، وعن أخلاقها، وعما يتعلق بالترغيب فيها؛ حتى تقدم على بصيرة. ويستحب لك النظر إليها، إذا تيسر النظر تنظر إليها بإذن أهلها، أو بغير إذن، إذا تيسر النظر إليها، ولو بغير إذن أهلها في من كوة.. من باب.. من جهة أخرى، وهي في المرعى، من غير خلوة قال جابر  \"خطب امرأة، فلم يزل يتخبأ حتى نظر إليها\" والنبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل وقال لرجل تزوج امرأة: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها. فالمقصود: النظر إليها مستحب إذا تيسر، ولو من دون علمها، لكن من دون خلوة، كأن ينظرها من بعيد، وهي في غنمها، أو في مجلس عند أهلها، أو ما أشبه ذلك. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16232/افضلية-مشاورة-الاب-في-اختيار-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77009.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":17374,"question":"في آخر أسئلة هذا السائل يقول: سماحة الشيخ هل يحق لي أن آخذ رأي والدي في البحث عن زوجة، وبدون أن أراها، أو أعرفها؟","title":"أفضلية مشاورة الأب في اختيار الزوجة","answer":"الجواب: الأفضل أن تشاور أباك، هذا من الأدب، ومن البر أن تشاوره فيمن تخطب، تقول: يا والدي! ممكن أريد فلانة، تشاور فيه، وتشاور من يعلمها من أهل الخير، ولا تعجل حتى تطمئن إلى أنها طيبة صالحة لقوله ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك تسأل عن دينها، وعن أخلاقها، وعما يتعلق بالترغيب فيها؛ حتى تقدم على بصيرة. ويستحب لك النظر إليها، إذا تيسر النظر تنظر إليها بإذن أهلها، أو بغير إذن، إذا تيسر النظر إليها، ولو بغير إذن أهلها في من كوة.. من باب.. من جهة أخرى، وهي في المرعى، من غير خلوة قال جابر  \"خطب امرأة، فلم يزل يتخبأ حتى نظر إليها\" والنبي ﷺ قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل وقال لرجل تزوج امرأة: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها. فالمقصود: النظر إليها مستحب إذا تيسر، ولو من دون علمها، لكن من دون خلوة، كأن ينظرها من بعيد، وهي في غنمها، أو في مجلس عند أهلها، أو ما أشبه ذلك. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16232/افضلية-مشاورة-الاب-في-اختيار-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77009.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":17432,"question":"من القصيم رسالة وقع صاحبها في نهايتها بالحرفين (م. م) يقول في رسالته: والدي متزوج من أربع نساء، وله أربعة عشر ولدًا وعشرون بنتًا، فمجموع الأولاد أربعة وثلاثون، والمشكلة كما يقول: إن أبي لا ينفق علينا إطلاقًا جميعًا بما في ذلك جدتي (والدته).. ثم يستمر في وصف والده فيقول: إنه غني غناء فاحشًا -كما يقول- ويملك عقارات كثيرة، وبنى ستة مساجد بتكلفة أربعة ملايين ريال تقريبًا، وهو يزكي، ويصلي، ويتصدق كثيرًا، ويساعد المحتاجين، ولكنه معنا على العكس من الآخرين، وعندما ناقشته؛ برر تصرفه بقوله: عندما أموت سوف تنسونني .. ويستمر في رسالته على هذا المنوال، ويرجو من سماحتكم التوجيه له، ولإخوته، ولوالده.","title":"توجيه لمن يكثر التصدُّق ويقصر في نفقة أهله","answer":"الجواب: ما ذكرته عن والدك من الأعمال الطيبة يسر كل مسلم، فجزاه الله خيرًا، وتقبل منه أعماله الطيبة في تعمير المساجد، والصدقة على الفقراء، والمحاويج، أما ما يتعلق بنفقته على زوجاته، وأولاده فهذا غلط، لابد أن ينفق على زوجاته، بل يجب عليه أن ينفق على زوجاته، والله -جل وعلا- أوجب عليه ذلك، قال -جل وعلا-: وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ [البقرة:233] يعني: الوالدات، يعني: الزوجات، وقال النبي ﷺ في الحديث الصحيح لما ذكر الزوجات قال: ولهن عليكم رزقهن، وكسوتهن بالمعروف. فالواجب عليه أن ينفق عليهن بالمعروف، هذا واجب عليه، وحق عليه، وكذلك أنتم إذا كنتم قاصرين فقراء؛ وجب عليه أن ينفق عليكم، على الذكور والإناث جميعًا، على الوالد أن ينفق على أولاده إذا كانوا محاويج. أما من كان فيكم غني، مستغني عن والده، عنده أسباب تقوم بحاله؛ فلا يلزم والده النفقة عليه، إنما ينفق على المحتاج، فإذا كان بعض البنات قد تزوج، واستغنى بالزوج، أو عندها مال، وعندها وظيفة، وهكذا الأولاد إذا كان عندهم وظائف، أو أكساب أخرى تغنيهم؛ فلا يلزمه أن ينفق عليهم. أما ما يتعلق بالورث فهذا الله هو الذي أعطاكم إياه، ما هو الذي أعطاكم هو، إذا مات وأنتم موجودون فلكم الورث أغنياء، أو فقراء، لكن عليه في الحياة أن يتقي الله، وأن يراقب الله سبحانه، فينفق على من يستحق النفقة منكم لفقره وحاجته، وعلى الزوجات أيضًا مطلقًا، ومن كان منكم غنيًا من ذكر وأنثى؛ فلا يلزمه ذلك، لا يلزمه الإنفاق عليه؛ لأنه مستغنٍ بما أعطاه الله من المال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16307/توجيه-لمن-يكثر-التصدق-ويقصر-في-نفقة-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83610.mp3","categories":["النفقات","بر الوالدين"]},{"id":17450,"question":"يقول هذا السائل: سماحة الشيخ! والدي هداه الله لا يصلي في المسجد، وإنما يصلي في البيت، ناصحته كثيرًا، فهل علي إثم تجاه والدي؟ وبماذا تنصحونني أن أفعل مأجورين؟","title":"واجب الابن تجاه أبيه التارك لصلاة الجماعة","answer":"الجواب: عليك أن تنصحه بالكلام الطيب، والأسلوب الحسن، ولا تقطع الزيارة؛ لأن حقه عظيم، قال الله في حق الولد مع الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما كافران حق، الوالد عظيم، تزوره، تدعو له بالتوفيق والهداية، توصيه بالصلاة في المسجد، وأبشر بالخير، ولا تفعل بشيء يؤذيه من كلام سيئ، أو وجه معبس، لا، انبسط إليه، وتكلم معه، وانصحه، وادع له بالهداية، والتوفيق، ولا تقطع زيارته، حقه عظيم الوالد والوالدة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16319/واجب-الابن-تجاه-ابيه-التارك-لصلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77207.mp3","categories":["حكم الصلاة وأهميتها","الخِطْبَة والاختيار ","بر الوالدين"]},{"id":17562,"question":"السائل الذي رمز لاسمه (ب. ف. ق) من الرياض يذكر بأنه شاب منَّ الله عليه بالهداية فيحمد الله على هذه النعمة ويسأل ويقول: فضيلة الشيخ! كنت فيما سبق آخذ من حرز أبي مبالغ كثيرة من المال دون علمه، وكان أخذي لها مستمر، وهي كثيرة جدًا لا أستطيع أن أرجعها إلى أبي، وأخشى إن أخبرته أن يغضب عليَّ، أو أن يفقد هذه الثقة الذي أولاها بي، ما الحكم يا فضيلة الشيخ إن أخذت مرة أخرى من مال أبي لتسديد إجار شقة أسكن فيها للدراسة؟ حيث أنني طالب ومكافأة الجامعة لا أستطيع القيام بها لجميع حقوقي، مع العلم بأنني أخشى إن طلبت من أبي أن يرفض ويغضب عليَّ؟","title":"حكم أخذ الابن من مال أبيه دون علمه","answer":"الجواب: لا يجوز لك أن تأخذ من مال أبيك بغير علمه، الواجب عليك أن تسأله، وأن تستأذن في ذلك إلا إذا كنت تأكل في بيته وقصر في نفقتك تأخذ بقدر الحاجة ككسوتك وأكلك إذا كان قصر، كما أذن النبي ﷺ لزوجة أبي سفيان هند أن تأخذ من ماله بالمعروف ما يكفيها ويكفي أولادها، فإذا كنت في نفقته وفي بيته، وقصر عليك، وليس عندك قدرة على التمام تأخذ من ماله بالمعروف حاجتك في لباس ونحو ذلك.. أما الأموال التي أخذتها زائدة على هذا فالواجب عليك ردها ولو بغير علمه، عليك أن تردها في ماله ولو بغير علمه، وإن استأذنته، وخبّرته، واستسمحته، ورددتها؛ فلا بأس، وإذا كنت تخشى أن يغضب ردها في ماله ولو بغير علمه. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16479/حكم-اخذ-الابن-من-مال-ابيه-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77519.mp3","categories":["النفقات","بر الوالدين"]},{"id":17611,"question":"الرسالة التالية وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: سائلة من السودان، تقول عن نفسها: أنا امرأة والحمد لله ملتزمة بالدين ولي والدة لم يطب لها التزامي بالدين وخاصة الحجاب الشرعي، وقد طلقها أبي منذ فترة وكنت في رعايتها بعد الله .وبعد أن تزوجت بأحد الإخوة الملتزمين رفضت والدتي زيارتي إليها، وما زلت بعد ذلك أزورها أنا وزوجي فإذا بها ترفض رفضًا باتًا مقابلتي عند بيتها، وكتبت لزوجي خطابات فحواها أنها ستعيش في قلق وضيق إذا زارها هو وابنتها فعليها التوقف عن زيارتها لتعيش مطمئنة حسب قولها، فهل في مثل هذه الحالة إذا انقطعت عن زيارة والدتي إرضاء لها أكون عاقة لها، علمًا بأن قلبي يتفطر ألمًا في مسلك والدتي هذا، حيث أنني لم أنقص من حقها شيئًا في الطاعة في المعروف جزاكم الله خيرًا.","title":"هل يجوز طاعة الوالدة في طلبها عدم زيارتها؟","answer":"الجواب: أنت مأجورة ومشكورة وعليك طاعة الله ورسوله، عليك أن تطيعي الله ورسوله في كل شيء ولو غضبت الوالدة أو غير الوالدة، يقول النبي ﷺ: إنما الطاعة في المعروف، ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق.\nفالوالدة والوالد والأمير والسلطان والزوجة والزوج كلهم لا يطاعون في معاصي الله، لا أحد يطاع في معاصي الله أبدًا، ولكن عليك الدعاء لها بالتوفيق والهداية والصلاح والإحسان إليها إذا كانت محتاجة بالمال والرفق، وإذا كلمتها بالتلفون ورضيت بالكلام فلا بأس وإلا ليس عليك إثم، الإثم عليها هي، أما أنت ليس عليك إثم، إذا كنت فعلت ما شرع الله لك من الحجاب وغضبت من أجل الحجاب فهذا غلط منها وجهل منها فاسألي الله لها التوفيق والهداية والصلاح، وأحسني إليها بالدعاء لها أن الله يوفقها وأن الله يهديها وأن الله يفقهها في الدين، وأن الله يعيذها من الشيطان وأبشري بالخير. وليس عليك حرج إذا ما زرتيها إذا كانت ترغب ألا تزوريها، ولا تؤذيها بالزيارة، وإن سمحت بالمكالمة التلفونية أو بالمكاتبة فافعلي، وإن لم تسمح فلا تفعلي أيضًا، وأنت معذورة ومشكورة ومأجورة والإثم على أمك، فاسألي الله لها الهداية، وأن الله يسامحها ويعفو عنها وأبشري بالخير، ونسأل الله لأمك الهداية، نسأل الله لأمك الهداية وأن يوفقها للفقه في الدين وأن يرزقها البطانة الصالحة التي ترشدها إلى الخير. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16540/هل-يجوز-طاعة-الوالدة-في-طلبها-عدم-زيارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84203.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":18025,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من حائل، باعثة الرسالة إحدى الأخوات المستمعات، الواقع تأثرت كثيرًا لهذه الرسالة إذ تقول فيها سماحة الشيخ:إنني فتاة ولي خمسة إخوة اثنان منهم متزوجون، وأنا أعمل معلمة، وإخواني هؤلاء البعض منهم يعمل والبعض يدرس، ووالدي يأخذ مني راتبي كله يعطيه إخوتي حيث يتصرفون فيه في عدة مجالات منهم من يشتري بها كتب، ومنهم من يشتري أشياء خاصة، ومنهم من تزوج بها، ومنهم من اشترى سيارة، ومنهم من يأخذ منها ليكمل بناء بيته، حيث أنني أعمل منذ سنوات عديدة، وكل أموالي تصرفوا بها ولم أعارض في ذلك، واحترامًا لوالدي وبرًا به وإحسانًا فأنا لا أريد إلا رضا الوالدين.سؤالي: هل يصح لوالدي أخذ أموالي هذه مع أنني أتعب كثيرًا لتحصيلها ليعطيها إخوتي وجهوني؟ جزاكم الله خيرًا.","title":"حكم أخذ الأب مرتب ابنته وإعطائه لأبنائه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد قال النبي الكريم عليه الصلاة والسلام في الحديث الصحيح: اتقوا الله واعدلوا بين أولادكم فوالدك له أن يأخذ من مرتبك ما يحتاجه في نفقته على بيته وأولاده القاصرين لقول النبي ﷺ: إن أطيب ما أكلتم من كسبكم وإن أولادكم من كسبكم، وقوله ﷺ لرجل قال له: يا رسول الله! إن أبي اجتاح مالي، قال: أنت ومالك لأبيك. فلا حرج عليه أن يأخذ من مالك ومال غيرك من أولاده ما يحتاجه بشرط عدم الضرر عليك وعلى غيرك ممن يأخذ ماله، فيأخذ من مالك مالا يضرك ومن مال أولاده الآخرين ما لا يضرهم لحاجته في نفقته على نفسه وزوجته وأولاده القاصرين للحديثين السابقين. أما أن يأخذ مرتبك لأولاده الآخرين فهذا لا يجوز إلا برضاك إذا سمحت من نفس طيبة وأذنت له أن يتصرف في ذلك فلا حرج؛ لأن المال مالك فإذا سمحت فلا حرج وإلا فليس له ذلك، أما أن يأخذ المال منك لينفقه على نفسه وعلى أولاده القاصرين الذين تلزمه نفقتهم فهذا لا حرج عليه وليس بجائر، وإذا كنت في حاجة إلى شيء فحاجتك مقدمة، حاجتك أنت مقدمة من كسوتك وحاجاتك الأخرى أنت مقدمة، وما فضل عن حاجتك له التصرف فيه في حاجته هو. أما أن يعطيه أولاده الآخرين ليبنوا بيوتًا أو لغير ذلك من المقاصد الأخرى فلا. أما النفقة التي فرض الله عليه أن ينفقها عليهم فهذا لا بأس أن يتصرف فيما يأخذه منك ومن غيرك في الإنفاق على الآخرين القاصرين الذين هم في حاجة إلى أبيهم وإلى نفقة أبيهم، وإذا سمحت بالمرتب كله يتصرف فيه كيف يشاء فلا حرج في ذلك والحمد لله. نعم. المقدم: جزاكم الله خيرًا. سماحة الشيخ! بعض الآباء يعتقد أن حديث رسول الله ﷺ: أنت ومالك لأبيك يعتقد أن هذا الحديث مطلق وليس له أي قيد، هل توجهون الآباء بشيء في هذه المناسبة؟ الشيخ: مثلما تقدم عند أهل العلم مقيد بعدم الضرر لقوله ﷺ: لا ضرر ولا ضرار والقاعدة الشرعية: أنه لا ضرر أحد لأحد، فلا يضر هذا الولد للولد الثاني، ولا يضر هذه البنت للبنت الثانية، ولكن يأخذ من مالهم ما يحتاجه هو ولا يضرهم، فلو كانت البنت عندها أولاد صغار ما لهم من يقوم عليهم ليس له أن يأخذ من مالها ما يضرها ويضر أولادها هم أولى، وهكذا إذا كانت تحتاج إلى ملابس وإلى كتب تنفعها في دروسها وإلى أشياء نحو ذلك فلابد أن يدع لها ما يقضي حاجتها لا يأخذ منها كل شيء، والقاعدة: لا ضرر ولا ضرار، فلابد أن يدع لها ما يسد حاجتها ويأخذ الفاضل لحاجته. وهكذا لو كان ذكرًا يترك له ولأولاده وزوجته ما يكفيهم ويأخذ من الزائد الفضل، لقوله ﷺ: لا ضرر ولا ضرار  قاعدة شرعية لا يضار أحد بأحد، لابد من عدم الضرر. نعم. المقدم: جزاكم الله خيرًا، فيما إذا أرادت هذه السائلة أن تتزوج أو تبني مسجدًا أو تتصدق كيف تتصرف مع والدها؟ الشيخ: حق والدها مقدم على المسجد وعلى غير المسجد. المقدم: حق والدها؟ الشيخ: ولدها مقدم. المقدم: لكن إذا كان الوالد مستغنيًا مثلًا؟ الشيخ: له أن يأخذ، ما زاد عن حاجتها له أن يأخذ، فبره مقدم على بناء المسجد، بره مقدم، أما حاجتها هي في ملابسها وأكلها وطعامها وأولادها مقدم، تقدم حاجتها هي وأولادها على الوالد، لكن ما فضل عن حاجتها وحاجة أولادها مثلًا له أن يأخذ ما يصرفه في حاجاته. نعم. المقدم: جزاكم الله خيرًا. الشيخ: جمعًا بين الأحاديث. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17052/حكم-اخذ-الاب-مرتب-ابنته-واعطاىه-لابناىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85005.mp3","categories":["النفقات","بر الوالدين"]},{"id":18071,"question":"رسالة وصلت إلى البرنامج من الأعظمية في بغداد وباعثتها إحدى الأخوات من هناك، رسالتها مطولة في الواقع، أستأذن سماحة الشيخ في أن أقرأها كما وردت.تقول: بسم الله الرحمن الرحيم وبه نستعين، والصلاة والسلام على محمد وعلى آله وأصحابه أجمعين:رسالتي لكم رسالة أم مؤمنة مسلمة عاشت عمرها الذي تجاوز الخمسين عامًا على عبادة الله وعلى سنة نبيه الكريم ﷺ أنشأت ابنتها الكبيرة على طريقتها حتى تزوجت قبل عشر سنوات وصارت تبتعد عني رغم أني أتقرب إليها حيث لم ينجب زوجها ذرية لسبب فيه، وتركنا ذلك إلى مشيئة الله  وفي الفترة الأخيرة افتقدتها نهائيًا ولم أعلم عنها شيئًا وانقطعت أخبارها، وقد تركتني أنا الأم التي أنشأتها على طاعة الله والوالدين أفتش عنها في كل زاوية ودرب مشوشة الفكر قلقة مشدودة الأعصاب.علمًا بأني تحت العلاج الطبي والعمليات الجراحية التي أجريت لي حتى الآن لم تشف، أكرر: هل ما أمر به الله تعالى بالعطف على الوالدين ورعايتهم وعدم الإساءة لهم بالقول البسيط (أف)، كيف بهذا العمل الذي أقلقني في صلاتي وحرمني طعم الخشوع، أدعو أبناءنا إلى الطاعة فيما يرضي الله ورسوله، وليتركوا تعسفهم بالوالدين باسم الانقطاع الكلي لفكرهم وآرائهم التي ينقصها التجربة والعطف والواقع الذي يلف البشر.فالله الله بهذه الأم التي أرضعت وربت ودرست وعلمت وهذبت على شريعة المصطفى محمد ﷺ أن تعامل هكذا.أرجو منكم حفظكم الله إذاعة رسالتي أكثر من مرة فهي تستمع إلى ندوتكم المذاعة منذ سنوات كما نسمعها جميعًا، ودمتم، وآخر دعوانا أن الحمد لله رب العالمين. وتسأل أربعة أسئلة فيما يبدو على ضوء ما ذكرت فتقول:سماحة الشيخ! ما حكم الشرع في هذا العمل حيث خرجت بدون محرم معها وكذبت على والديها؟ما حكم الشرع في هذا العقوق ومعاملة الوالدين وهما من أهل الإسلام والإيمان؟ما درجة صحة حديث رسول الله ﷺ حينما أمر أحد المجاهدين بالرجوع عن الجهاد والبقاء مع أمه رأفة بها من نبي الرحمة الكريم ﷺ؟هل غاب عن بال من يصرف النظر عن والديه أن النبي الكريم أوصى بالأم ثلاث مرات وبالأب مرة دون غيرهم؟ أرجو أن تتفضلوا بالتوجيه والإرشاد حول هذه القضية.والواقع رسالة مطابقة تمامًا لهذا الموضوع لكن مرسلها أخونا عبد الله العبيدي من بغداد أيضًا، والموضوع واحد كما قلت سماحة الشيخ.","title":"وجوب بر الوالدين والعناية بهما","answer":"الجواب: لا ريب أن بر الوالدين والإحسان إليهما والرفق بهما من أهم الواجبات، ومن أفضل القربات، وقد أوجب الله سبحانه حق الوالدين وأمر بالإحسان إليهما في كتابه العظيم في آيات كثيرات؛ منها: قوله : وَقَضَى رَبُّكَ أَلاَّ تَعْبُدُوا إِلاَّ إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَاناً إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنْ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23-24]. ومنها: قوله سبحانه في سورة لقمان: أَنْ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]. فبرهما من أهم الفرائض، وهذا العمل الذي عملته هذه البنت عمل سيئ ومنكر ولاشك أنه عقوق، والواجب عليها أن تضع يدها في يد والدتها، وأن تطلب منها السماحة والإباحة والعفو؛ لأنها قد أساءت إلى والدتها مع ما فعلت الوالدة من الخير العظيم والتربية والإحسان والصبر على أذى الطفل.. إلى غير ذلك مما تقوم به الوالدة، فينبغي لهذه البنت أن تتوب إلى الله وأن ترجع إليه سبحانه وأن تستغفره جل وعلا من ذنبها وتقصيرها، وأن تضع يدها في يد والدتها وتستسمحها وتطلبها العفو. وإذا كان هناك شيء حصل من والدتها يضرها ففي إمكانها توسيط من ترى من أهل الخير والأقارب حتى يصلح بينها وبين والدتها إن كان هناك شيء أوجب هذه القطيعة وهذا البعد. وأما ما يتعلق بسفر المرأة بغير محرم فهذا لا يجوز، ليس لها أن تسافر إلا بمحرم كما أمر به النبي عليه الصلاة والسلام حيث قال: لا تسافر امرأة إلا مع ذي محرم وكذلك قال النبي عليه الصلاة والسلام لما قال له رجل: «يا رسول الله! من أبر؟ قال: أمك  قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب. وفي اللفظ الآخر يقول عليه الصلاة والسلام لما سئل قيل: «يا رسول الله! أي الناس أحق بحسن الصحبة؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك. فحق الوالدة أعظم وأكبر من حق الوالد ثلاث مرات، حتى الجهاد إذا كان ليس فرض عين لابد من استئذان الوالدين أو أحدهما إذا كان الموجود أحدهما وهو الجهاد الذي هو من أهم الفرائض وقد يجب على الأعيان في بعض الأحيان. فالحاصل أنه يجب على الولد أن يستأذن والديه في الجهاد إذا لم يكن فرض عين لعظم حقهما ولهذا قال عليه الصلاة والسلام لما استأذنه رجل للجهاد قال: أحي والداك؟ قال: نعم. قال: ففيهما فجاهد. فالمقصود: أن حق الوالدين عظيم، فالواجب على البنين والبنات أن يعنوا بهذا الأمر وأن يعطفوا على والديهم وأن يرحموا والديهم، وأن يحسنوا إلى الوالدين، وأن يتلطفوا بالوالدين، ويعطفوا على الوالدين، فهذا من بعض حق الوالدين، رزق الله الجميع التوفيق والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17106/وجوب-بر-الوالدين-والعناية-بهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_902/nour_90206.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":18145,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (ع. م. أ. الكناني ) من القنفذة.أخونا رسالته مطولة في الواقع ملخصها سماحة الشيخ: أن والده بدأ ينازعه على راتبه، وهو أب لأسرة تتكون من أربعة أشخاص، ويقول: إنه دفع نصف المرتب لوالده، إلا أن الوالد لم يرتض بذلك؛ نظرًا لأن الوالد نفسه يعول أسرة كبيرة فيها تسعة أنفس ويرجو من سماحة الشيخ التوجيه؟ جزاكم الله خيرًا.","title":"توجيه لمن يطالبه أبوه بالتنازل عن جميع راتبه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد دل كتاب الله العزيز وسنة رسوله الأمين عليه الصلاة والسلام على عظم شأن الوالدين وعلى عظم حقهما وعلى وجوب برهما، فالواجب على الولد أن يحرص على بر الوالدين، وأن يخصهما بمزيد عناية؛ لأن الله  يقول: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23] الآية، وفي معناها آيات أخرى، وقال جل وعلا: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]، وقال النبي عليه الصلاة والسلام: إن أطيب ما أكلتم من كسبكم وإن أولادكم من كسبكم، وجاءه رجل يشتكي أن أباه اجتاح ماله، فقال: أنت ومالك لأبيك. فالواجب عليك أن تتحرى ما يرضي والدك، وأن تحرص على إقناعه بالأسلوب الحسن والعبارات اللطيفة، فتدع لولدك وأهل بيتك ما يكفيهم، وتعطيه ما يعينه على نفقة عائلته، وبذلك يحصل لك الأجر العظيم وبر والدك. أما إن كان النصف الذي يبقى لك لا يكفي حاجتك أو لا يزيد عن حاجتك فلا يلزمك: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وقد دل على هذا قوله ﷺ: لا ضرر ولا ضرار، حق الوالدين عظيم، ولكن لا ضرر ولا ضرار إذا كان الباقي من راتبك بقدر حاجتك من دون إسراف ولا تبذير، فلا يلزمك أن تعطيه الزيادة، لكن تعتذر إليه بالعبارات الحسنة وبالأساليب الطيبة، أو توسط بعض أقاربك حتى يعتذروا عنك وحتى يرضوه عنك، هذا هو الذي ينبغي لك في هذه المسألة. أما إن كان عندك قدرة على الزيادة وأن تخفض النصف وتعطيه زيادة على النصف وأن هذا يكفيك ويكفي من تحت يدك، حاجة متوسطة ليس فيها إسراف ولا تبذير فافعل ذلك. والخلاصة: أنك تجتهد في إرضاء والدك، لكن من دون ضرر عليك، وعلى أهل بيتك؛ لأن عليك حقًا لزوجتك وأهل بيتك أولادك، وعليك حق لوالدك، فإذا جاء الضرر قدمت حاجة نفسك وحاجة ولدك، وليس لوالدك إلا ما فضل وزاد على هذا، لما تقدم من قوله ﷺ: لا ضرر ولا ضرار، ولقوله ﷺ: ابدأ بنفسك ثم من تعول، فأنت تبدأ بنفسك وأبوك ممن تعول، فتبدأ بنفسك وأهل بيتك، ثم تعطي والدك ما زاد مما يسد حاجته ويعينه على نفقة عياله، يسر الله أمرك وأعانك وبارك لك وعليك وأغنى والدك. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17187/توجيه-لمن-يطالبه-ابوه-بالتنازل-عن-جميع-راتبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_853/nour_85301.mp3","categories":["النفقات","بر الوالدين"]},{"id":18183,"question":"من المستمع: (ح. ب. أبو سعيد )، رسالة ضمنها جمعًا من الأسئلة، في أحدها يقول: هل يحق للأب أن يأخذ مال ابنه، وممتلكاته بحجة أن الرسول ﷺ قال: أنت ومالك لأبيك؟","title":"حكم أخذ الأب جميع مال ابنه","answer":"الجواب: نعم، له أن يأخذ من مال ابنه، من مال ابنه ما شاء، إذا لم يضر ابنه، أنت ومالك لأبيك، ويقول عليه الصلاة والسلام: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم؛ لكن ليس له أن يضره، بل يجب أن يترك له ما يكفيه، وإن كان له ذرية، وزوجة كذلك، لابد أن يترك له ما يكفيه وزوجته وأولاده؛ لقوله ﷺ: لا ضرر، ولا ضرار، لا ضرر، ولا ضرار، فليس له أن يضر ولده. أما إذا كان ولده ما عنده أحد، وأخذ ماله وصار ينفق عليه؛ فلا بأس، لكن الأفضل للوالد أن يتعاطى الأمور التي لا تجعل الأولاد يبغضونه، ويكرهونه، ويتمنون زواله، ينبغي له أن يلاحظ خواطرهم، وأن لا يطمع في أموالهم، لكن يأخذ ما يحتاج إليه، يأخذ من أموالهم ما لا يضرهم، فيما يحتاج إليه. أما يتعمد ضررهم، فلا يجوز له ذلك، بل لابد أن يدع لهم ما يحتاجون إليه، ولاسيما إذا كان لهم أولاد، لهم زوجة، لابد يترك لهم ما هو كاف، ولا يتسبب في تعطيل أمرهم، وضررهم، لقوله ﷺ: لا ضرر، ولا ضرار. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17221/حكم-اخذ-الاب-جميع-مال-ابنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73112.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":18184,"question":"من المستمع: (ح. ب. أبو سعيد )، رسالة ضمنها جمعًا من الأسئلة، في أحدها يقول: هل يحق للأب أن يأخذ مال ابنه، وممتلكاته بحجة أن الرسول ﷺ قال: أنت ومالك لأبيك؟","title":"حكم أخذ الأب جميع مال ابنه","answer":"الجواب: نعم، له أن يأخذ من مال ابنه، من مال ابنه ما شاء، إذا لم يضر ابنه، أنت ومالك لأبيك، ويقول عليه الصلاة والسلام: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم؛ لكن ليس له أن يضره، بل يجب أن يترك له ما يكفيه، وإن كان له ذرية، وزوجة كذلك، لابد أن يترك له ما يكفيه وزوجته وأولاده؛ لقوله ﷺ: لا ضرر، ولا ضرار، لا ضرر، ولا ضرار، فليس له أن يضر ولده. أما إذا كان ولده ما عنده أحد، وأخذ ماله وصار ينفق عليه؛ فلا بأس، لكن الأفضل للوالد أن يتعاطى الأمور التي لا تجعل الأولاد يبغضونه، ويكرهونه، ويتمنون زواله، ينبغي له أن يلاحظ خواطرهم، وأن لا يطمع في أموالهم، لكن يأخذ ما يحتاج إليه، يأخذ من أموالهم ما لا يضرهم، فيما يحتاج إليه. أما يتعمد ضررهم، فلا يجوز له ذلك، بل لابد أن يدع لهم ما يحتاجون إليه، ولاسيما إذا كان لهم أولاد، لهم زوجة، لابد يترك لهم ما هو كاف، ولا يتسبب في تعطيل أمرهم، وضررهم، لقوله ﷺ: لا ضرر، ولا ضرار. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17221/حكم-اخذ-الاب-جميع-مال-ابنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73112.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":18428,"question":"تسأل أختنا وتقول: هل لي أن أسمع نداء أبي أو أمي إذا كان الفيديو أو ما شابه الفيديو مفتوحًا وبه فلم أو أمراني بالجلوس معهما؟ وهل يحق لهما منعي من قراءة الكتب النافعة التي تزيد بصيرتي في الدين؟","title":"حكم إجابة الوالدين وفي حضرتهما منكر","answer":"الجواب: ليس للوالدين ولا غيرهما أن يمنعا البنت أو الولد الذكر من قراءة الكتب النافعة، وليس لهما أيضًا أن يلزما الذكر أو البنت بحضور أفلام خليعة لا خير فيها، كل هذا ليس لهم ذلك، وليس للولد أن يطيعهما في المعصية، وله أن يخالفهما لكن بالأسلوب الحسن والكلام الطيب؛ لقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق . ولا شك أن منع الوالدين للولد ذكرًا كان أو أنثى، لا شك أن منعهما له من قراءة الكتب المفيدة، أمر لا يجوز ومنكر، وكل إنسان في حاجة إلى الكتب المفيدة، من ذكر وأنثى. وهكذا دعوتهما الولد، ذكر وأنثى إلى أن يحضر الأفلام الخليعة، والأشياء المنكرة في تلفاز أو فلم أو غيره، لا شك أن دعوة الوالد لهما للبنت أو الابن دعوة منكرة، لا يلزمهما طاعته في ذلك، بل لا يجوز لهما طاعته في ذلك، إذا كان ذلك مما حرم الله ؛ لأن الله نهى عن حضور المنكر، وأمر بالبعد عن ذلك، وأمر أيضًا باجتناب ما حرم الله، وعدم التعاون على الإثم والعدوان، ونهى عن طاعة المخلوق في معصية الخالق، فليس للولد ذكرًا كان أو أنثى أن يستجيب لدعوة أبيه أو أمه فيما حرم الله. نعم. المقدم: جزاكم الله خيرًا. إذًا هناك حد معين لطاعة الوالدين؟ الشيخ: نعم، في المعروف، هذا الحد. المقدم: الطاعة في المعروف. الشيخ: المعروف هو المشروع والمباح، أما المعصية فلا، لكن عليهما أن يعني: على الولد ذكرًا كان أو أنثى عليه أن يعتني بالأسلوب الحسن والكلام الطيب، والدعاء لوالديه بالتوفيق والهداية، يا والدي رحمك الله، يا أبي رضي الله عنك، يا أمي رحمك الله، يا والدتي! غفر الله لك، هذا شيء لا يجوز، هذا شيء لا أتمكن من الاستجابة إليه، يعني: بعبارات طيبة، بعبارات لبقة لطيفة ليس فيها عنف؛ لأن الله قال في حق الوالدين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] ولو كانا كافرين، فكيف بالمسلمين. وقال الله سبحانه: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ [لقمان:14] وقال: وَبِالْوَالِدَيْنِ إِحْسَانًا [البقرة:83]. نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17507/حكم-اجابة-الوالدين-وفي-حضرتهما-منكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_914/nour_91403.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":18582,"question":"تقول السائلة من جدة: هل يجوز لطالب العلم أن يترك والدته وحيدة ويذهب لطلب العلم الشرعي؟","title":"حكم ترك أحد الوالدين للذهاب لطلب العلم","answer":"الجواب: هذا فيه تفصيل، إذا كان عندها من يقوم بحالها، ويخدمها، ويقضي حاجاتها؛ لا بأس؛ لأن طلب العلم واجب، فعليه أن يؤمن حاجاتها، ويذهب لطلب العلم، ولا بأس ولا حرج، والحمد لله، نعم. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم الإسلام والمسلمين.","link":"https://binbaz.org.sa/fatwas/17706/حكم-ترك-احد-الوالدين-للذهاب-لطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78624.mp3","categories":["بر الوالدين","العالم والمتعلم"]},{"id":18663,"question":"رسالة مطولة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: المرسلة (ع. ي. ز. هـ) الرسالة مكونة من ثلاث صفحات، أختنا مشكلتها: أن ابن عمها تقدم لخطبتها، والجميع موافقون إلا والدتها لم توافق على ذلك؛ بسبب أحقاد قديمة فيما بين الأسرتين، وترجو من سماحة الشيخ التوجيه لأولياء الأمور في هذا، جزاكم الله خيرًا.","title":"حكم زواج البنت بغير رضا أمها","answer":"الجواب: الواجب على أولياء المرأة، وعلى أمها، وعلى أقاربها الموافقة إذا خطبها الكفء، الكفء في دينه، المستقيم الموافقة على ذلك؛ لما روي عنه -عليه الصلاة والسلام- أنه قال: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد كبير وفي اللفظ الآخر: وفساد عريض ولأن المرأة على خطر إذا جلست بدون زوج، وهي أهل للزواج، ولا سيما في هذا العصر، فإن الخطر أكبر. فالواجب على الأولياء وعلى أم المرأة وعلى جدتها وعلى أخواتها أن يسهلوا في ذلك، وأن يسهلوا الأمر، وأن لا يشددوا إذا كان الخاطب مرضيًا في دينه لا حرج فيه، فإن أبت الأم ولم ترض فلا مانع أن تزوج بغير إذنها إذا وافق الأب وكان الزوج مرضيًا، وعليها أن تستسمح أمها بما تستطيع ولو بعد الزواج. المقدم: ولو بعد الزواج. الشيخ: ولو بعد الزواج؛ لأن الرسول  يقول: إنما الطاعة في المعروف هكذا يقول النبي ﷺ: إنما الطاعة في المعروف ويقول: لا طاعة لمخلوق في معصية الخالق. وترك الزواج مع تيسر الزواج، ومع وجود الخاطب إما معصية، وإما مكروه جدًا، والأقرب أنه معصية؛ لقول النبي ﷺ: يا معشر الشباب، من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج وهذه استطاعت ويسر الله لها الزواج، ورضي والدها -يعني: أباها- فالواجب المبادرة والمسارعة إلى هذا الخير حرصًا على عفة الفرج، وغض البصر، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17770/حكم-زواج-البنت-بغير-رضا-امها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91908.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":18823,"question":"من القطيف في المنطقة الشرقية، هذه رسالة وصلت إلى البرنامج من المستمع (م. ر. د) أخونا بدأ رسالته بقوله:بسم الله الرحمن الرحيم. أنا مدرس مصري أعمل بالمنطقة الشرقية، ومدين لبرنامجكم الخالد: نور على الدرب؛ وإذ نشكركم ونتوجه بالدعاء للقائمين عليه، وممن خلف البرنامج ولعلمائنا الأفاضل، جعلكم وجعلهم الله ذخرًا لنا في ديننا ودنيانا. السؤال الأول هو: أنا مقيم بالمملكة بصحبة أسرتي المكونة من زوجتي وولدين، أما والدي الذي يعيش في مصر فتقدم به العمر، ولكنه ما زال يشتغل بالتجارة في محله البسيط، ساعيًا على أخي الذي أنهى دراسته هذا العام، والتحق بالخدمة العسكرية، وعلى أخواتي البنات الاثنتين، ولكن والدي يربطان رضاهم علي بمساعدة أخي المادية، وتحملي نفقة زواجه، وحتى قبل أخواتي البنات، ومن أجل ذلك قطعوا اتصالهم بي، واعتبروني عاقًا لهما، رغم أنني مريض بمرض مزمن، وكم أخشى من المجهول على مصير أولادي وأخشى ما أخشاه، وما يؤرقني عدم رضا الوالدين علي. فأرجو من سماحتكم تبصيري كيف أتصرف تجاه ما يطلب مني الوالدان؟جزاكم الله خيرًا.","title":"حكم طاعة الوالدين في أمرهما بالنفقة على الإخوان","answer":"الجواب: الواجب عليك أن تتقي الله ما استطعت؛ فإن استطعت أن تصل والديك وترضيهما فافعل بما يسر الله لك، بعد حاجتك وحاجة أولادك وزوجتك، فإن لم يتيسر فأنت معذور، واعتذر إليهما بذلك، فإن النفقة عليك وعلى أولادك مقدمة، فعليك أن تنظر في الأمر، وأن تجتهد وتحرص على إرضاء والديك بما يسر الله لك من المال، حتى يرضيا عنك، وحتى تساعد أخاك وأنت على خير عظيم، ولو خففت النفقة على نفسك وأهلك بعض التخفيف الذي لا يضر الجميع لإرضاء والديك، فهذا أمر مطلوب، فاجتهد في الاقتصاد والحرص على أن توفر شيئًا ترضي به والديك، جزاك الله خيرًا. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17955/حكم-طاعة-الوالدين-في-امرهما-بالنفقة-على-الاخوان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92107.mp3","categories":["النفقات","بر الوالدين"]},{"id":18933,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية السودان، وباعثها أحد الإخوة يقول: ابنكم عمر ملوان -فيما يبدو- أخونا رسالته مطولة، وكتبها بلهجته العامية السودانية، فهمت منها سماحة الشيخ: أن أمه غير مسلمة، ويسأل عن البر بها بعد وفاتها، كيف تنصحونه سماحة الشيخ؟","title":"حكم بر الوالدة الكافرة بعد وفاتها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: ما دامت توفيت فليس هناك شيء يلحقها بعد الوفاة؛ لأن الكافر لا يلحقه شيء بعد الوفاة، ما دامت ماتت على دين النصرانية أو الوثنية، فلا تدع عليها، ولا تدع لها، ولا يلحقها منك شيء، لا صدقة، ولا استغفار، ولا غير ذلك، إنما هذا في حق الميت المسلم: إذا مات انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له أما إذا كنت تعلم أنها ماتت على النصرانية أو اليهودية أو الوثنية وعبادة القبور، فهذه لا يلحقها شيء منك، لا تدع لها، ولا تتصدق عنها، وإنا لله وإنا إليه راجعون، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18066/حكم-بر-الوالدة-الكافرة-بعد-وفاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92401.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":19072,"question":"من جمهورية مصر العربية المستمع (ع. س. س. ع) له قضية يقول فيها: إنني رجل متزوج، والحمد لله أعمل في الخارج، ووجود زوجتي معي ضروري شرعًا، لكن أترك والدتي وحيدة علمًا بأنني العائل الوحيد لها، وتكون تحت رعاية أختي المتزوجة، ولكن لا أسافر إلا بموافقتها، وهي تتمنى أن أجلس معها، وألغي سفري؛ لأن سفري يؤلمها مع العلم بأن وجود زوجتي معها يخفف من آلامها، فهل أمكث معها، وألغي سفري نهائيًا؟ أم أبقي معها زوجتي، وليس علي حرج في تأثر والدتي؟ جزاكم الله خيرًا.","title":"حكم سفر الابن لطلب الرزق تاركًا أمه وحيدة","answer":"الجواب: هذا فيه تفصيل: إذا أمكنك العمل في المحل الذي فيه والدتك، وأن تجبر خاطرها، وترضيها؛ فهذا أولى؛ لأن مراعاة خاطرها من أهم المهمات، ومن أفضل القربات. أما إذا كنت مضطرًا للسفر لطلب الرزق، وليس في بلدك سبب يعينك على حاجتك، ويسبب غناك عن السفر؛ فأنت معذور في هذا، الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]. وإذا كان لا يضرك بقاء الزوجة عند أمك فأبقها عند أمك جبرًا لها، وإيناسًا لها، أما إذا كان عليك خطر وتخشى على نفسك فإنك تسافر بزوجتك تطلب من الوالدة السماح، ومتى سمحت فالحمد لله، فإن لم تسمح فهذا محل نظر؛ لأن الرسول ﷺ يقول: إنما الطاعة في المعروف. وأنت قد يكون عليك ضرر كبير في بقائك بدون زوجة في بلاد الغربة، فالأقرب والله أعلم أنه يجوز لك السفر بها، وإن لم ترض الوالدة من أجل الضرورة، وشدة الحاجة إليها معك؛ حرصًا على عفتك، وسلامتك، وسلامتها أيضًا. ولكن مهما أمكن أن تستسمح الوالدة، وتجتهد في رضاها عنك؛ فهو أولى وأكمل، يسر الله أمرك، وقضى حاجتك. المقدم: آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18267/حكم-سفر-الابن-لطلب-الرزق-تاركا-امه-وحيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79704.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]},{"id":19328,"question":"أخ لنا يقول: المرسل ولدكم المعذب -كما يصف نفسه - عبد الله بن علي المعيطب من الرياض: والدي سماحة الشيخ عبد العزيز أفتوني عن أمر ضاق به صدري، وحالتي الصحية تأثرت به كثيرًا، إنني عصيت والدي كثيرًا وفي يوم من الأيام حصلت لي قضية، وقام والدي بالمتابعة لها، وأثناء هذا حدثت له حادثة سيارة وتعذب كثيرًا في المستشفى، ثم توفي وهو غير راض عني، وفي بعض الأوقات يقول أهلي: إنني أنا الذي قتلته، وأنا الذي تسببت في هذا الحادث، وهذه الكلمات تجرح قلبي، وفي بعض الأوقات أفكر - كما يقول شيخ عبدالعزيز - في الانتحار بسبب تلكم الكلمات، أنا الآن أدعو لوالدي، وأقرأ له القرآن إلا أن حالتي الصحية في تأثر، كيف أكفر عما فعلت تجاه والدي، وبماذا تنصحونني وتنصحون أهلي؟ جزاكم الله خيرًا.","title":"كيفية التوبة من عقوق الوالد بعد وفاته","answer":"الجواب:  أما أنت فننصحك بأن تلزم التوبة النصوح التي تشتمل على الندم على ما فعلت مع والدك من الإساءة، والعزم الصادق أنك لا تعود إلى أمثال ذلك من العقوق والقطيعة، وعليك مع ذلك أن تتبع هذا بالعمل الصالح كما قال الله  في كتابه العظيم : إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ [الفرقان:70]، قال سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]. فنصيحتي لك أن تلزم التوبة والندم على ما مضى منك، وتكثر الاستغفار والعمل الصالح من صلاة وصدقات وغير ذلك، وتسبيح وتهليل وتحميد وتكبير، وتكثر من قراءة القرآن وغير هذا من العمل الصالح، مع الدعاء لوالدك بالمغفرة والرحمة ورفيع الدرجة في الجنة، وتتصدق عنه بما تستطيع. الصدقات تنفع والدك، أما قراءة القرآن عنه فليس عليها دليل؛ وإن قال بها جمع من أهل العلم، لكن الأفضل أن تجعل بدل القراءة له الدعاء؛ لأنه لم يرد دليل واضح على أنه يقرأ عن الأموات، وإنما الدعاء هو المشروع، الدعاء له، والصدقة عنه، والحج عنه، والعمرة عنه، كل هذا أمر ينفعه، يقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية أو علم ينتفع به أو ولد صالح يدعو له، كن أنت ولدًا صالحًا، وأكثر من الدعاء والاستغفار لأبيك مع توبتك الصادقة عما جرى منك سابقًا وأبشر بالخير، والتوبة تجب ما قبلها والحمد لله، وإياك والوساوس، وإياك وطاعة من يقول لك: إنك فعلت وإنك فعلت.. التوبة تهدم ما كان قبلها، وتجب ما قبلها الحمد لله، أعظم من العقوق الشرك، وإذا تاب المشرك تاب الله عليه؛ فالعقوق دون الشرك، فالتوبة تجب ما قبلها. ونصيحتي لأهلك أن يتقوا الله فيك، وأن لا يتعرضوا لهذا الأمر وأن يبشروك بالخير؛ لأنك تبت والتوبة تجب ما قبلها فلا يجوز لهم أبدًا أن يذكروك بما جرى منك مما يضرك، ويسبب ضيق صدرك وتحرجك، بل ينبغي لهم أن يسلوك عن هذا، وأن يقولوا لك: احمد لله لما تاب عليك، وليس لك في هذا الحادث ما يوجب تأثرك، فالأمر بيد الله  هو الذي قضى ما قضى، ويرجى له الخير، ولعله يكون شهيداً بسبب الحادث. فالحاصل أن الواجب عليك التوبة فقط ولزومها، ويشرع لك الدعاء لأبيك والإكثار من ذلك، والصدقة كما تقدم إذا تيسرت ولو بالقليل، والحج إذا تيسر عن والدك والعمرة كذلك، كل هذا طيب. وأبشر بالخير وإياك وسوء الظن بالله وإياك وسوء الظن بالله من تاب أفلح من تاب أفلح، يقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، والرسول عليه الصلاة والسلام يقول: التوبة تهدم ما كان قبلها، ويقول: التائب من الذنب كمن لا ذنب له، فاتق الله وأحسن الظن بمولاك واستقم على طاعته جل وعلا ولا تلتفت إلى من يلومك أو يقول لك بعد هذا فهم مخطئون وغالطون في كونهم يؤذونك وقد تبت إلى الله، بل الواجب عليهم أن يبشروك، وأن يفرحوك، وأن يعينوك على الفرح وحسن الظن بالله فالتائب لا يؤذى، التائب يبشر ويعان. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18534/كيفية-التوبة-من-عقوق-الوالد-بعد-وفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_896/nour_89603.mp3","categories":["إهداء القرب للميت","زيارة القبور","الحكم على الأحاديث","بر الوالدين"]},{"id":19702,"question":"إنني رجلٌ قد تزوجتُ وأبقيتُ زوجتي حسب رغبة الوالد عنده، ومُصرٌّ والدي ألا أغترب بهذه الزوجة، علمًا بأن الزوجة لا تريد أن تُفارقني، فهل أنا مذنبٌ إن تركتُ المرأة عند والدي، أم أنا مذنبٌ إن أخذتُها منه وهو غاضبٌ وأكون عاقًّا لوالدي؟","title":"حكم طاعة الوالدين في ترك الزوجة عندهم والسفر وهو محتاج لها","answer":"الجواب: إذا أمكن الجمع بين المصالح بأن تذهب وترجع بين وقتٍ آخر وتتركها عند والدك لحاجة والديك إليها، وأنت لا تتأخر كثيرًا، بين شهرٍ وشهرٍ ترجع إليها، وتقوم بحاجتها وملاحظة ما تُريد، وتُرضي والديك، هذا طيبٌ. أما إذا كنتَ تحتاج إليها ولا تتمكن من المجيء إليهم، فحاجاتك مقدَّمة؛ تذهب بها معك، وتستسمح والدك، وليس له طاعةٌ في هذا؛ لأنك محتاجٌ لها: تعفّك وتُعينك على محاربة الشيطان، فتذهب بها، ولا طاعةَ لمخلوقٍ في معصية الخالق؛ لأنَّ ذهابك وحدك يُعرضك لأمورٍ خطيرةٍ، وهي أيضًا كذلك قد تتعرض لأمورٍ خطيرةٍ في جلوسها.\nفالواجب أن تأخذها معك، وأن تعفّ بها فرجك، وتغضّ بها بصرك، وتستسمح الوالد بالكلام الطيب، وتُشير عليه بأن يسمح، وتستعين على ذلك بخواصّ الأقارب: كأعمامك أو أخوالك حتى يرضى عنك، أما تركها عندهم وأنت لا تستطيع الرجوع إليها بين وقتٍ قريبٍ لقضاء حاجتك وعفَّة فرجك فهذا لا يصلح، وهذا غلطٌ من أبيك.","link":"https://binbaz.org.sa/fatwas/20657/حكم-طاعة-الوالدين-في-ترك-الزوجة-عندهم-والسفر-وهو-محتاج-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0575%D8%AD%D9%83%D9%85%20%D8%B7%D8%A7%D8%B9%D8%A9%20%D8%A7%D9%84%D9%88%D8%A7%D9%84%D8%AF%D9%8A%D9%86%20%D9%81%D9%8A%20%D8%AA%D8%B1%D9%83%20%D8%A7%D9%84%D8%B2%D9%88%D8%AC%D8%A9%20%D8%B9%D9%86%D8%AF%D9%87%D9%85%20%D9%88%D8%A7%D9%84%D8%B3%D9%81%D8%B1%20%D9%88%D9%87%D9%88%20%D9%85%D8%AD%D8%AA%D8%A7%D8%AC%20%D9%84%D9%87%D8%A7%D8%9F%20%D8%A7%D8%A8%D9%86%20%D8%A8%D8%A7%D8%B2%20%D9%81%D8%AA%D8%A7%D9%88%D9%89%20%D8%A7%D9%84%D9%85%D8%AD%D8%A7%D8%B6%D8%B1%D8%A7%D8%AA.mp3","categories":["النظر والخلوة والاختلاط","بر الوالدين"]}]
